INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','easy','flashcard','What are the KDIGO diagnostic criteria for AKI?','["AKI is defined by: (1) Rise in serum creatinine ≥0.3 mg/dL within 48 hours, OR (2) Rise in serum creatinine ≥1.5× baseline within 7 days, OR (3) Urine output <0.5 mL/kg/h for ≥6 hours. KDIGO Stages: Stage 1 = Cr ×1.5–1.9 or +0.3 mg/dL or UO <0.5 mL/kg/h ×6–12h; Stage 2 = Cr ×2.0–2.9 or UO <0.5 mL/kg/h ×12h; Stage 3 = Cr ×3 or ≥4 mg/dL or UO <0.3 mL/kg/h ×24h or anuria ×12h or RRT initiated."]','A','KDIGO staging is based on creatinine rise relative to baseline OR urine output. Both criteria count independently — whichever gives the higher stage is used.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','flashcard','What is the FENa formula and how is it used in AKI?','["FENa (%) = (UNa × SCr) / (SNa × UCr) × 100. FENa <1% = prerenal azotemia (intact tubular reabsorption). FENa >2% = intrinsic AKI/ATN (tubular damage). Exceptions: FENa <1% can occur in early ATN from contrast or myoglobin; FENa >2% in diuretic-treated prerenal states (use FEUrea instead: <35% = prerenal)."]','A','FENa is the gold standard urine index for differentiating prerenal from intrinsic AKI — a critical bedside investigation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','flashcard','What are the urinary findings in prerenal azotemia vs ATN?','["Prerenal: BUN:Cr >20:1; FENa <1%; Urine osmolality >500 mOsm/kg; Urine Na <20 mEq/L; Hyaline casts (normal). ATN: BUN:Cr ~10–15:1; FENa >2%; Urine osmolality ~290 mOsm/kg (isosthenuria); Urine Na >40 mEq/L; Muddy brown granular casts, renal tubular epithelial cells."]','A','These indices differentiate the two most common categories of AKI — knowing them allows targeted management without waiting for biopsy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','hard','flashcard','What are the absolute indications for emergency dialysis in AKI (AEIOU mnemonic)?','["A = Acidosis (pH <7.1 refractory to bicarbonate); E = Electrolyte disturbance (hyperkalaemia K+ >6.5 with ECG changes, refractory to medical treatment); I = Intoxication (dialysable toxins: ethylene glycol, methanol, salicylates, lithium); O = Overload (pulmonary oedema refractory to diuretics); U = Uraemia (pericarditis, encephalopathy, uraemic bleeding, asterixis)."]','A','These are the cardinal indications for RRT in AKI — memorised as AEIOU. The presence of any one is sufficient to initiate dialysis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','easy','flashcard','What are the three categories of AKI and their distinguishing features?','["1. PRERENAL: Reduced renal perfusion (hypovolaemia, heart failure, NSAIDs, ACE inhibitors). No structural damage. Responds to fluids. 2. INTRINSIC (Renal): Glomerular (GN), tubular (ATN — most common), interstitial (AIN), vascular (TTP, vasculitis). 3. POSTRENAL: Obstruction (BPH, stones, malignancy). Requires relief of obstruction. Ultrasound shows hydronephrosis."]','A','Classifying AKI into prerenal/intrinsic/postrenal guides management — treat the underlying category before starting dialysis.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','flashcard','Name four common nephrotoxic drugs and their mechanisms causing AKI.','["1. Aminoglycosides (gentamicin) — proximal tubular cell toxicity via megalin uptake → ATN. 2. NSAIDs — inhibit prostaglandins → reduce renal afferent vasodilation → prerenal AKI; chronic use → papillary necrosis. 3. Contrast media — medullary vasoconstriction + direct tubular toxicity. 4. Cisplatin — DNA damage to proximal tubular cells → ATN. Also: vancomycin (interstitial nephritis), amphotericin B (distal tubular damage, nephrogenic DI)."]','A','Nephrotoxin avoidance and monitoring is key in hospitalised patients — aminoglycosides + NSAIDs account for >30% of hospital-acquired AKI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','flashcard','What is the management of contrast-induced nephropathy (CIN) prevention?','["Prevention: 1. Use iso-osmolar/low-osmolar contrast (not high-osmolar). 2. IV hydration: 0.9% NaCl or sodium bicarbonate 1–3 mL/kg/h for 6–12 hours before and after. 3. Minimise contrast volume. 4. Hold nephrotoxic drugs (NSAIDs, metformin) beforehand. 5. N-acetylcysteine (600 mg BD) — modest evidence. 6. Avoid 24-48h between contrast procedures. Define CIN: Cr rise ≥0.5 mg/dL or ≥25% within 48–72h after contrast."]','A','CIN is the 3rd most common cause of hospital-acquired AKI. Prevention is primarily adequate IV hydration before and after contrast administration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','hard','flashcard','What is hepatorenal syndrome (HRS) and how is Type 1 HRS managed?','["HRS is functional renal failure in cirrhosis/acute liver failure without structural kidney disease. Mechanism: extreme splanchnic vasodilation → reduced effective circulating volume → renal vasoconstriction. Type 1: rapidly progressive (Cr doubles to >2.5 mg/dL in <2 weeks), poor prognosis. Type 2: gradual, associated with refractory ascites. Diagnosis: cirrhosis + renal failure after excluding other causes (infection, hypovolaemia, drugs). Management: Terlipressin + albumin infusion (25 g/day); stop diuretics; liver transplantation is definitive."]','A','HRS has >90% mortality without liver transplant. Terlipressin + albumin is the only pharmacological treatment with strong evidence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','easy','flashcard','What fluid should be used for resuscitation in prerenal AKI?','["Isotonic crystalloid (0.9% NaCl or Ringer''''s lactate) is first-line for fluid resuscitation in prerenal AKI. Give 250–500 mL bolus IV over 15–30 minutes and reassess. Avoid hypotonic fluids (worsen hyponatraemia). Avoid colloids (albumin, starch) as first-line. In sepsis, target MAP >65 mmHg. In haemorrhage, use blood products. Monitor urine output response — improvement within 1–2 hours confirms prerenal cause."]','A','The appropriate fluid and rate of resuscitation are critical — over-resuscitation causes pulmonary oedema, under-resuscitation allows progression to ATN.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','flashcard','What is the role of CRRT vs intermittent haemodialysis in critically ill AKI patients?','["CRRT (Continuous Renal Replacement Therapy — CVVH, CVVHD, CVVHDF) is preferred in haemodynamically unstable ICU patients because: gradual fluid removal prevents hypotension; continuous solute clearance; better cerebral perfusion pressure control. Intermittent HD: more efficient per session; better for poisoning (rapid toxin removal); easier in stable patients. CRRT allows: 1–2 L/h fluid removal; nutritional support volume; continuous drug clearance adjustment. Outcomes similar between CRRT and IHD when adequately dosed."]','A','Choice between CRRT and IHD depends on haemodynamic stability, not superiority — both are appropriate when used correctly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','easy','flashcard','What are the KDIGO CKD stages by eGFR?','["G1: eGFR ≥90 mL/min/1.73m² (normal/high); G2: 60–89 (mildly decreased); G3a: 45–59 (mild-moderate); G3b: 30–44 (moderate-severe); G4: 15–29 (severely decreased); G5: <15 (kidney failure/ESRD). Diagnosis requires: eGFR <60 OR markers of kidney damage (proteinuria, haematuria, structural abnormality) persisting ≥3 months. Albuminuria categories: A1 <30 mg/g (normal); A2 30–300 (moderately increased); A3 >300 (severely increased)."]','A','CKD staging using both eGFR (G1–G5) and albuminuria (A1–A3) creates a heat map of risk — high eGFR + high proteinuria still carries risk.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','flashcard','What causes anaemia in CKD and how is it managed?','["Causes: (1) Reduced erythropoietin production (main cause); (2) Iron deficiency (absolute — reduced absorption; or functional — TSAT <20%); (3) Chronic inflammation suppressing erythropoiesis; (4) Reduced RBC lifespan (uraemic haemolysis); (5) Blood loss from dialysis, phlebotomy. Management: Optimise iron first (IV iron if TSAT <20% or ferritin <200 on dialysis); then ESA (epoetin alfa or darbepoetin alfa) if Hb <10 g/dL; target Hb 10–12 g/dL (not >13 — cardiovascular risk). Hypoxia-inducible factor prolyl hydroxylase inhibitors (roxadustat) — emerging oral alternative."]','A','ESAs are the cornerstone of anaemia management in CKD, but iron optimisation must come first — many patients respond to IV iron alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','flashcard','What is CKD-MBD and how is it managed?','["CKD-Mineral Bone Disorder: triad of elevated phosphate, low calcium, and elevated PTH due to: (1) Reduced 1α-hydroxylase activity → low calcitriol → hypocalcaemia; (2) Reduced GFR → phosphate retention; (3) Both → secondary hyperparathyroidism. Complications: renal osteodystrophy (osteitis fibrosa cystica, osteomalacia), vascular calcification, cardiovascular mortality. Management: (a) Dietary phosphate restriction; (b) Phosphate binders (calcium carbonate/acetate, sevelamer, lanthanum — avoid excess calcium in vascular calcification); (c) Active vitamin D (calcitriol/alfacalcidol); (d) Calcimimetics (cinacalcet) if PTH very high and calcifications present."]','A','CKD-MBD is a major cause of cardiovascular mortality in CKD — phosphate control and PTH management are essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','hard','flashcard','Which drugs slow CKD progression in diabetic nephropathy and by what mechanism?','["1. ACE inhibitors/ARBs: dilate efferent arteriole → reduce intraglomerular hypertension → reduce proteinuria 30–50% → slow fibrosis. 2. SGLT2 inhibitors (empagliflozin, dapagliflozin, canagliflozin): reduce proximal tubular glucose reabsorption → tubuloglomerular feedback → efferent dilation → reduce hyperfiltration → anti-inflammatory and anti-fibrotic effects. Also reduce cardiovascular events (EMPA-REG, CREDENCE, DAPA-CKD trials). 3. Finerenone (non-steroidal MRA): reduces aldosterone-driven inflammation/fibrosis in diabetic CKD (FIDELIO-DKD). Target: BP <130/80, HbA1c ~7%, proteinuria minimised."]','A','ACE inhibitors + SGLT2 inhibitors are now dual standard of care in CKD — their mechanisms are complementary and additive for nephroprotection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','easy','flashcard','What dietary advice should a CKD stage 4 patient receive?','["1. Protein: 0.6–0.8 g/kg/day (reduce hyperfiltration and uraemia burden); higher on dialysis (1.2 g/kg/day to replace dialysis losses. 2. Phosphate: Restrict to <800 mg/day (processed foods, soft drinks high in phosphate additives). 3. Potassium: Restrict if hyperkalaemia (avoid bananas, oranges, potatoes — unless well-boiled). 4. Sodium: <2000 mg/day (reduces proteinuria, oedema, BP). 5. Fluid: Usually unrestricted until Stage 5 unless oliguric. 6. Energy: 30–35 kcal/kg/day to prevent catabolism."]','A','Dietary management in CKD is complex and individualized — phosphate control (preventing CKD-MBD) and sodium restriction (BP control) are highest priority.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','flashcard','What are the complications of untreated metabolic acidosis in CKD?','["1. Accelerated CKD progression: ammonia-mediated complement activation, tubular injury, interstitial fibrosis. 2. Muscle wasting: acid activates the ubiquitin-proteasome pathway → protein catabolism. 3. Bone disease: buffering of acid by bone → calcium/phosphate release → osteomalacia, fractures. 4. Growth retardation in children. 5. Insulin resistance. 6. Cardiovascular effects. Treatment: Oral sodium bicarbonate (1–3 g/day in divided doses); target serum HCO3 >22 mEq/L. Note: sodium load may worsen hypertension and fluid retention."]','A','Treating metabolic acidosis in CKD with sodium bicarbonate slows CKD progression — large RCTs (including UK trial BICAR-ICU) support this.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','flashcard','What are the indications for referral to a nephrologist in CKD?','["Urgent/emergent: AKI on CKD; rapidly declining eGFR (>5 mL/min/year); eGFR <30 (G4/G5) for RRT planning. Routine: eGFR <45 + diabetes; eGFR <30 in anyone; proteinuria A2/A3 unexplained; suspected glomerular or renovascular disease; resistant hypertension on ≥3 drugs; CKD-MBD not controlled by GP. Pre-dialysis: ideally referred ≥12 months before anticipated RRT start for fistula formation (AV fistula matures in 3–6 months), transplant evaluation, dietary counselling."]','A','Early referral at CKD G4 gives time for RRT planning — arteriovenous fistula should be formed at least 6 months before needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','hard','flashcard','Describe the renin-angiotensin-aldosterone system (RAAS) activation in CKD and its consequences.','["In CKD: Reduced renal perfusion → juxtaglomerular cells release renin → angiotensinogen → angiotensin I → ACE → angiotensin II. AngII causes: (1) Vasoconstriction (efferent > afferent) → glomerular hypertension; (2) Aldosterone release → sodium/water retention → hypertension, oedema; (3) Direct profibrotic effects on mesangial cells; (4) TGF-β induction → fibrosis. Consequences: hypertension (resistant), progressive CKD, left ventricular hypertrophy, cardiovascular risk. ACE-I/ARBs block this cascade — reduce proteinuria, slow CKD progression."]','A','RAAS activation is the central pathophysiological mechanism driving CKD progression — ACE inhibitors and ARBs target it directly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','easy','flashcard','What are the signs and symptoms of uraemia in CKD stage 5?','["Neurological: asterixis (metabolic flap), confusion, uraemic encephalopathy, peripheral neuropathy, restless leg syndrome. Cardiovascular: pericarditis (uraemic friction rub), accelerated atherosclerosis. GI: anorexia, nausea/vomiting, hiccups, uraemic fetor (ammonia breath), GI bleeding. Haematological: bleeding tendency (platelet dysfunction), anaemia. Dermatological: uraemic frost (urea crystals on skin — rare), pruritus, pallor. These are indications for dialysis."]','A','Uraemic symptoms indicate dialysis is overdue — pericarditis and encephalopathy are emergency indications requiring urgent RRT.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','flashcard','How does diabetic nephropathy progress histologically?','["Stage I: Glomerular hypertrophy + hyperfiltration (increased GFR). Stage II: Mesangial expansion without clinical disease (silent). Stage III: Microalbuminuria 30–300 mg/day (incipient nephropathy) — first clinical sign; GFR normal or elevated. Stage IV: Overt nephropathy — proteinuria >300 mg/day (macroalbuminuria), declining GFR, hypertension; pathology shows Kimmelstiel-Wilson nodules (nodular glomerulosclerosis), diffuse GBM thickening. Stage V: ESRD, GFR <15. Kimmelstiel-Wilson nodules = PAS-positive eosinophilic nodules in mesangium = pathognomonic of diabetic nephropathy."]','A','Microalbuminuria is the earliest clinical marker of diabetic nephropathy — screen all diabetics annually. Intervene at Stage III to prevent progression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','easy','flashcard','What are the four cardinal features of nephrotic syndrome?','["1. Heavy proteinuria >3.5 g/24 hours (or protein:creatinine ratio >300 mg/mmol). 2. Hypoalbuminaemia <3.5 g/dL (due to urinary loss + increased catabolism). 3. Peripheral oedema (periorbital, ankle — from low oncotic pressure + sodium retention). 4. Hyperlipidaemia (LDL elevated — liver upregulates VLDL synthesis to compensate for low oncotic pressure). Additional: lipiduria (oval fat bodies, fatty casts on urine microscopy)."]','A','Nephrotic syndrome is a clinical diagnosis defined by heavy proteinuria + hypoalbuminaemia + oedema — hyperlipidaemia and lipiduria are characteristic but not defining.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','flashcard','What are the thrombotic complications of nephrotic syndrome and why do they occur?','["Venous thromboembolism occurs in 25–40% of nephrotic patients, especially in membranous nephropathy. Mechanisms: (1) Urinary loss of anticoagulants: antithrombin III, protein C, protein S → thrombophilic state; (2) Elevated fibrinogen and coagulation factors V, VII, VIII, X (large molecules retained); (3) Platelet hyperaggregability; (4) Reduced fibrinolysis. Classic: renal vein thrombosis (presents with acute flank pain, haematuria, AKI — Doppler USS or CTV confirms). Also: DVT, PE, arterial thrombosis. Prophylactic anticoagulation if albumin <2.0 g/dL in membranous nephropathy."]','A','Renal vein thrombosis is the classic complication of membranous nephropathy — always consider it in nephrotic patients with sudden flank pain or AKI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','flashcard','Compare the causes of nephrotic syndrome in children vs adults.','["CHILDREN: Minimal change disease (MCD) — 80% of cases, steroid-responsive, excellent prognosis. Focal segmental glomerulosclerosis (FSGS) — 2nd most common, may be steroid-resistant. ADULTS: Membranous nephropathy — most common primary (anti-PLA2R+). FSGS — most common in African-Americans. MCD — less common but occurs at all ages. SECONDARY CAUSES (any age): Diabetic nephropathy (most common globally), amyloidosis, lupus nephritis Class V, myeloma, drugs (NSAIDs, gold, penicillamine), infections (HBV, HCV, HIV, malaria)."]','A','MCD is the dominant cause in children (steroid-responsive); membranous nephropathy dominates in adults. Secondary causes must always be excluded.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','hard','flashcard','What is the mechanism of oedema formation in nephrotic syndrome?','["Two mechanisms: 1. UNDERFILL hypothesis (classical): Low albumin → reduced plasma oncotic pressure → fluid moves from intravascular to interstitial → hypovolaemia → renin-angiotensin-aldosterone activation → sodium/water retention. 2. OVERFILL hypothesis: Primary tubular defect → sodium retention → increased plasma volume → oedema (despite relatively preserved oncotic pressure). Evidence: Most nephrotic patients have normal or elevated plasma volume. Clinical impact: Hypovolaemic patients need albumin before diuresis; hypervolaemic patients need aggressive diuretics. Check BP orthostasis to assess volume status."]','A','The ''''overfill'''' vs ''''underfill'''' distinction guides treatment — volume-depleted nephrotic patients should not receive aggressive diuresis without albumin replacement.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','easy','flashcard','What is the mechanism of hyperlipidaemia in nephrotic syndrome?','["Low serum albumin → low plasma oncotic pressure → hepatic upregulation of lipoprotein synthesis (apoB-100, VLDL). Simultaneously, lipoprotein lipase (LPL) activity is reduced (urinary loss of LPL cofactor) → impaired lipoprotein clearance. Result: elevated total cholesterol, LDL, VLDL, triglycerides; normal or low HDL. Hyperlipidaemia + urinary protein lipid complexes → lipiduria (oval fat bodies, Maltese cross birefringence on polarised light). Treatment: statins (prevent cardiovascular events); address underlying nephropathy to resolve hyperlipidaemia."]','A','Nephrotic hyperlipidaemia directly increases cardiovascular risk — statins should be started and maintained until remission.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','flashcard','What are the principles of immunosuppression in primary membranous nephropathy?','["Conservative therapy first for 6 months (RAAS blockade, statin, anticoagulation if albumin <2.5). Treat if: proteinuria >8 g/24h persistently, declining GFR, or severe symptoms. Immunosuppression options: 1. Modified Ponticelli regimen (Ponticelli protocol): alternating months of IV methylprednisolone (months 1,3,5) and oral chlorambucil or cyclophosphamide (months 2,4,6) for 6 months. 2. CNI-based: tacrolimus or cyclosporine for 12 months (alternative if Ponticelli unsuitable). 3. Rituximab: anti-CD20 B-cell depletion — increasingly preferred (MENTOR trial); targets anti-PLA2R producing plasma cells. Monitor anti-PLA2R titre for response."]','A','Rituximab has emerged as the preferred first-line immunosuppression for primary membranous nephropathy due to favourable efficacy and safety profile.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','flashcard','What infection risks are associated with nephrotic syndrome?','["Increased susceptibility to: 1. Encapsulated bacteria (Streptococcus pneumoniae, Haemophilus influenzae) — urinary loss of IgG opsonins; 2. Gram-negative peritonitis (spontaneous bacterial peritonitis in children — E. coli, Klebsiella); 3. Varicella-zoster (from steroid immunosuppression). Mechanisms: (a) Urinary IgG loss → hypogammaglobulinaemia; (b) Complement loss (factor B, D → reduced alternative pathway); (c) Steroid immunosuppression. Prevention: pneumococcal vaccine before steroid therapy; annual influenza vaccine; prophylactic penicillin in children with frequent relapses."]','A','Pneumococcal vaccine is mandatory before immunosuppression in nephrotic syndrome — encapsulated bacteria are the primary infectious risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','hard','flashcard','What is FSGS and what are the histological variants with their prognoses?','["FSGS = focal (<50% glomeruli affected) and segmental (<100% of glomerular tuft) sclerosis. Variants (Columbia classification): 1. NOS (Not Otherwise Specified) — most common; 2. Tip variant — sclerosis at tubular pole → best prognosis, most steroid-responsive; 3. Collapsing variant — worst prognosis (HIV-associated nephropathy; podocytopathy); 4. Perihilar variant — obesity-related; 5. Cellular variant — active lesion. Genetic forms (NPHS2/podocin, ACTN4/alpha-actinin-4, TRPC6) — do not respond to steroids; require transplantation. Primary FSGS = podocyte injury; secondary = adaptive hyperfiltration, drugs (bisphosphonates, interferon)."]','A','Collapsing FSGS has the worst prognosis (rapid ESRD); Tip variant has the best steroid response — variant identification guides treatment decisions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','easy','flashcard','What is the first-line treatment for minimal change disease in children?','["Prednisolone 60 mg/m²/day (max 60 mg) for 4–6 weeks, followed by 40 mg/m² on alternate days for 4–6 weeks then taper. Response: 90% achieve complete remission within 4 weeks (complete remission = urine protein <0.3 g/day for 3 consecutive days). Relapses: common (50–70% relapse); manage with repeat prednisolone course. Frequent relapsers/steroid-dependent: cyclophosphamide (cumulative dose limited), tacrolimus, mycophenolate mofetil, or rituximab. MCD in adults: also steroid-responsive but slower (6–16 weeks) and more relapses."]','A','MCD in children is the most steroid-responsive glomerular disease — 90% remission with prednisolone alone. Consider alternative if no response at 8 weeks.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','flashcard','How should proteinuria be monitored in nephrotic syndrome during treatment?','["Spot urine protein:creatinine ratio (PCR) or albumin:creatinine ratio (ACR) — replace cumbersome 24-hour collections. Definitions: Complete remission = PCR <100 mg/mmol (<1 g/g) or urine protein <0.3 g/day. Partial remission = PCR 100–350 mg/mmol or protein 0.3–3.5 g/day (50% reduction from baseline). No response = protein >3.5 g/day. Monitor monthly during induction, 3-monthly in remission. Serum albumin normalisation usually lags behind proteinuria reduction. Anti-PLA2R titres in membranous nephropathy predict response before proteinuria falls."]','A','PCR/ACR on spot urine sample is now standard — a single first-morning void PCR correlates well with 24-hour urine protein.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','easy','flashcard','What are the clinical features of nephritic syndrome?','["The classic nephritic tetrad: 1. HAEMATURIA — macroscopic (cola/tea-coloured) or microscopic with RED CELL CASTS (pathognomonic of glomerular bleeding). 2. HYPERTENSION — from sodium/water retention + renin activation. 3. OLIGURIA — reduced urine output due to reduced GFR. 4. VARIABLE PROTEINURIA — usually sub-nephrotic (<3.5 g/day) but can overlap. Also: oedema (less severe than nephrotic), elevated creatinine/BUN. AKI is common."]','A','Red cell casts are pathognomonic of glomerular haematuria and nephritic syndrome — they form when RBCs pass through disrupted GBM and are moulded in tubular lumina.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','flashcard','What is the complement pattern in different forms of GN?','["LOW C3, NORMAL C4 (alternative pathway): Post-streptococcal GN, MPGN Type II (C3 nephritic factor). LOW C3 AND C4 (classical pathway): Lupus nephritis, cryoglobulinaemic GN, MPGN Type I. NORMAL C3 AND C4: IgA nephropathy (Berger''''s), Alport syndrome, anti-GBM disease, ANCA vasculitis. Complement levels guide the differential diagnosis of GN — always check C3, C4 in a new GN presentation."]','A','The complement pattern is a critical first step in evaluating GN — C3 low + C4 normal = alternative pathway (post-strep, C3 nephropathy); both low = classical pathway (lupus).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','flashcard','What are the three types of rapidly progressive GN (RPGN) by immunofluorescence?','["Type I (Linear IgG — anti-GBM disease): Linear staining of IgG along entire GBM. Cause: Goodpasture''''s syndrome (± lung involvement). Treatment: Plasmapheresis + cyclophosphamide + steroids. Type II (Granular — immune complex): ''''Lumpy-bumpy'''' deposits. Causes: Post-streptococcal GN, lupus, IgA nephropathy. Treatment: Steroids ± immunosuppression per underlying cause. Type III (Pauci-immune — no deposits): Negative IF. ANCA-positive (>80%): GPA (c-ANCA/PR3) or MPA (p-ANCA/MPO). Treatment: Cyclophosphamide or rituximab + methylprednisolone."]','A','Crescent >50% glomeruli = RPGN by definition. IF pattern immediately narrows the diagnosis to one of three types — guides targeted treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','hard','flashcard','How is Goodpasture''''s syndrome diagnosed and treated?','["Goodpasture''''s: Anti-GBM antibodies against NC1 domain of type IV collagen α3 chain → Type II hypersensitivity. Presentation: Pulmonary haemorrhage + rapidly progressive GN (pulmonary-renal syndrome). Diagnosis: Serum anti-GBM antibodies (ELISA) + renal biopsy (crescentic GN with linear IgG on IF). Treatment (emergency): 1. Plasmapheresis (plasma exchange) — removes pathogenic antibodies (daily 4L exchanges × 2 weeks); 2. High-dose cyclophosphamide — prevent antibody production; 3. IV pulse methylprednisolone → oral prednisolone. Lung haemorrhage worsened by smoking and fluid overload — stop smoking urgently. If creatinine >600 µmol/L and oligoanuric at presentation — unlikely to recover renal function but treat to prevent lung haemorrhage."]','A','Anti-GBM disease is one of the few nephrology emergencies where plasmapheresis is proven life-saving — start within hours of diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','easy','flashcard','What is the typical clinical presentation of IgA nephropathy?','["IgA nephropathy (Berger''''s disease) is the most common primary GN worldwide. Presentation: 1. Synpharyngitic haematuria (macroscopic haematuria within 1–5 days of URTI — simultaneous, NOT 2–3 weeks later like post-strep GN); 2. Persistent microscopic haematuria (found on routine urinalysis); 3. Variable proteinuria (mild to nephrotic-range); 4. Hypertension and CKD develop over years. Histology: mesangial IgA deposits on IF; mesangial hypercellularity on LM. Oxford classification (MEST-C score) guides prognosis."]','A','The timing of haematuria distinguishes IgA nephropathy (synpharyngitic — same time as URTI) from post-streptococcal GN (1–3 weeks post-URTI).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','flashcard','What is the long-term prognosis of IgA nephropathy?','["25–30% of patients progress to ESRD within 20–25 years. Poor prognostic factors (Oxford MEST-C score): M1 (mesangial hypercellularity); E1 (endocapillary proliferation); S1 (segmental sclerosis); T1/T2 (tubular atrophy/interstitial fibrosis); C1/C2 (crescents). Other: sustained proteinuria >1 g/day, hypertension, impaired GFR at presentation, male sex. Treatment: ACE inhibitors (reduce proteinuria); optimise BP (<125/75 if proteinuria >1 g/day); fish oil (omega-3) — modest evidence; immunosuppression (steroids) for high-risk patients with eGFR >50; tonsillectomy — debated. Novel: SGLT2 inhibitors; sparsentan; targeted release budesonide (NEFECON)."]','A','IgA nephropathy has variable prognosis — 25% reach ESRD. Proteinuria >1 g/day despite ACE inhibitor is the threshold for considering steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','flashcard','What is ANCA-associated vasculitis affecting the kidney?','["ANCA vasculitis includes: GPA (Granulomatosis with Polyangiitis — formerly Wegener''''s; c-ANCA/anti-PR3; upper airway, lung, kidney); MPA (Microscopic Polyangiitis; p-ANCA/anti-MPO; kidney dominant); EGPA (Eosinophilic GPA — asthma, eosinophilia). Renal: pauci-immune focal necrotising GN with crescents (IF negative — no immune deposits). Presentation: haematuria, red cell casts, rapidly rising creatinine, systemic features (sinusitis in GPA, pulmonary haemorrhage in MPA). Induction: Cyclophosphamide + steroids OR Rituximab + steroids (equivalent). Plasma exchange if pulmonary haemorrhage or dialysis-dependent. Maintenance: Azathioprine or rituximab."]','A','ANCA vasculitis is pauci-immune (negative IF) — a key distinguishing feature. Rituximab is now a first-line induction option equivalent to cyclophosphamide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','hard','flashcard','How is post-streptococcal glomerulonephritis diagnosed and managed?','["Diagnosis: Clinical + supportive laboratory findings. Features: 1–3 weeks post-pharyngitis (3–6 weeks post-impetigo) → haematuria, oedema, hypertension; Low C3 (low C4 normal — alternative pathway); Elevated ASO titre (antistreptolysin O — if pharyngitis) or anti-DNase B (if impetigo); Urine: RBC casts, protein, pyuria. Biopsy (rarely needed): ''''lumpy-bumpy'''' granular IgG + C3 deposits on IF; subepithelial humps on EM (''''cookie-dough''''). Management: Supportive — antihypertensives, salt/fluid restriction, diuretics for oedema; Penicillin × 10 days to eradicate residual strep; No specific immunosuppression. Prognosis: Excellent in children (>95% recover fully); adults more likely to develop chronic kidney disease."]','A','Post-streptococcal GN does not require immunosuppression — treatment is purely supportive. The classic mistake is confusing timing with IgA nephropathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','easy','flashcard','What investigations should be performed in newly diagnosed GN?','["Blood: FBC, U&E, LFTs, creatinine, albumin. Immunology: ANA, anti-dsDNA, anti-Sm (lupus); ANCA (c-ANCA/PR3, p-ANCA/MPO); anti-GBM antibodies; complement C3, C4. Infection: ASO titre, anti-DNase B; Hepatitis B surface antigen + anti-HCV; HIV; blood culture if febrile. Urine: Microscopy (RBC casts, WBC), PCR, culture. Imaging: Renal USS (size, echogenicity, obstruction). Renal biopsy: if aetiology unclear, rapidly progressive, or to guide immunosuppression. Echocardiography if infective endocarditis suspected."]','A','A systematic immunological screen guides the differential diagnosis of GN — the pattern of complement, ANCA, ANA, anti-GBM, and ASO titre narrows the diagnosis rapidly.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','flashcard','What is lupus nephritis and how is it classified?','["ISN/RPS Classification: Class I: Minimal mesangial (normal LM; mesangial IgG on IF). Class II: Mesangial proliferative (mild, usually subclinical). Class III: Focal proliferative (<50% glomeruli; haematuria + proteinuria + mild renal impairment). Class IV: Diffuse proliferative (>50% glomeruli; most severe; wire-loop deposits; haematuria + heavy proteinuria + hypertension + rapidly declining GFR). Class V: Membranous (nephrotic syndrome; subepithelial deposits; can co-exist with Class III/IV). Class VI: Advanced sclerosing (>90% global sclerosis; irreversible; dialysis). Serological activity: low C3/C4, high anti-dsDNA titres. Class IV requires aggressive induction."]','A','Class IV diffuse proliferative lupus nephritis is the most severe and requires immediate induction with MMF or cyclophosphamide + steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','easy','flashcard','What is the target blood pressure in CKD with and without proteinuria?','["CKD without proteinuria (ACR <30 mg/g): Target BP <140/90 mmHg. CKD with proteinuria (ACR ≥30 mg/g): Target BP <130/80 mmHg (KDIGO 2021). Diabetic CKD: <130/80 mmHg. On dialysis: BP control guided by volume management; pre-dialysis target <140/90. Rationale: Lower BP targets in proteinuric CKD reduce progression; aggressive reduction may reduce GFR without benefit in non-proteinuric CKD (J-curve effect)."]','A','The proteinuria threshold drives BP targets in CKD — ACR ≥30 triggers a target of <130/80 rather than the standard <140/90.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','flashcard','Describe the mechanism and clinical features of renovascular hypertension.','["Renal artery stenosis (RAS) → reduced perfusion to juxtaglomerular apparatus → renin release → angiotensin II → systemic vasoconstriction + aldosterone → sodium retention → severe hypertension. Clinical clues: (1) Onset <30 years (fibromuscular dysplasia — young women) or >55 years (atherosclerosis); (2) Resistant hypertension on ≥3 drugs; (3) Flash pulmonary oedema (bilateral RAS); (4) Deterioration of renal function on ACE inhibitor; (5) Renal bruit; (6) Hypokalaemia (aldosterone excess). Investigation: Duplex Doppler USS (screening); CT or MR angiography (definitive). FMD: ''''string of beads'''' on angiography."]','A','Clinical clues distinguish FMD (young woman, string of beads) from atherosclerotic RAS (older, cardiovascular risk factors) — treatment differs significantly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','flashcard','What is malignant hypertension and how is it managed?','["Malignant hypertension = BP >180/120 mmHg + evidence of end-organ damage: retinopathy (Grade III haemorrhages, exudates; Grade IV papilloedema), encephalopathy (confusion, seizures), AKI, cardiac failure, microangiopathic haemolytic anaemia (MAHA) with schistocytes. Management: (1) Reduce BP gradually — not rapidly (risk of ischaemic stroke if too fast); target: reduce by 20–25% over first hour, then to 160/100 within 6 hours; (2) IV labetalol (first-line), nicardipine, or sodium nitroprusside; (3) Oral medication when stable; (4) Identify and treat cause (Conn''''s, phaeochromocytoma, RAS); (5) Dialysis if severe AKI. Avoid hydralazine (unpredictable)."]','A','Overly rapid BP reduction in malignant hypertension causes ischaemic organ injury — aim for controlled reduction over hours, not minutes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','hard','flashcard','How does renal hypertension develop in CKD and what are the mechanisms?','["Multiple mechanisms of hypertension in CKD: 1. Sodium/water retention → volume overload (dominant in dialysis). 2. RAAS activation → vasoconstriction + aldosterone-driven sodium retention. 3. Sympathetic nervous system overactivation (renal afferent nerve signalling from damaged kidney). 4. Reduced synthesis of vasodilators: prostaglandins (PGE2, PGI2), nitric oxide, kallikrein. 5. Endothelin-1 excess → vasoconstriction. 6. Arterial stiffness → systolic hypertension. 7. Secondary hyperparathyroidism → smooth muscle calcium uptake. Management: volume control (dialysis), ACE/ARB, amlodipine, beta-blockers."]','A','CKD hypertension is multifactorial — volume overload dominates in dialysis patients; RAAS activation and SNS drive hypertension in earlier CKD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','easy','flashcard','Which antihypertensive classes are contraindicated in bilateral renal artery stenosis and why?','["ACE inhibitors AND ARBs are contraindicated in bilateral RAS (or RAS in a solitary kidney). Reason: In bilateral RAS, GFR is maintained by angiotensin II-mediated efferent arteriolar constriction. ACE-I/ARBs block AngII → efferent dilation → precipitous fall in GFR → acute renal failure. Dual RAAS blockade (ACE-I + ARB) amplifies this risk. First-line alternatives: amlodipine (calcium channel blocker), doxazosin, beta-blocker. Monitor creatinine and potassium 1–2 weeks after starting ACE-I/ARB in any patient — a rise of 20–30% in creatinine triggers evaluation for RAS."]','A','A rise in creatinine >30% after starting ACE-I/ARB should prompt renal imaging to exclude bilateral RAS — not an automatic reason to stop the drug, but requires investigation.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','flashcard','What is the treatment of fibromuscular dysplasia of the renal artery?','["FMD: non-inflammatory, non-atherosclerotic arteriopathy affecting media of renal (and other) arteries. Most common in women aged 20–50. Angiographic appearance: ''''string of beads'''' (medial fibroplasia — most common type). Treatment: Percutaneous transluminal angioplasty (PTA) WITHOUT stenting — cure/significant improvement in 70–90% of cases (stent reserved for dissection or failure). Medical therapy (ACE-I/ARB + antiplatelet) for mild/incidental cases. FMD can also affect carotid and vertebral arteries — screen with whole-body MRA after diagnosis. Unlike atherosclerotic RAS, stenting offers no additional benefit over PTA."]','A','FMD responds dramatically to angioplasty alone — stenting is not routinely needed. This contrasts with atherosclerotic RAS where medical therapy usually suffices.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','flashcard','What is Conn''''s syndrome and how does it cause hypertension and hypokalaemia?','["Conn''''s syndrome = Primary hyperaldosteronism (most common cause: adrenal adenoma or bilateral adrenal hyperplasia). Mechanism: Excess aldosterone (autonomous, not angiotensin-dependent) → (1) Sodium retention in collecting duct → hypertension; (2) Kaliuresis + H+ secretion → hypokalaemia + metabolic alkalosis. Presentation: Resistant hypertension; spontaneous hypokalaemia (<3.5 without diuretics); muscle weakness, cramps; rarely tetany. Diagnosis: Plasma aldosterone:renin ratio (ARR) >30 (aldosterone elevated, renin suppressed). Confirm with salt loading or fludrocortisone suppression test. Localise with adrenal CT + adrenal vein sampling. Treatment: Adrenalectomy (adenoma) or spironolactone/eplerenone (bilateral hyperplasia)."]','A','Primary aldosteronism is the most common secondary cause of hypertension — suspect it in resistant hypertension + hypokalaemia, even without diuretics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','hard','flashcard','How is hypertensive nephrosclerosis diagnosed and does antihypertensive choice matter?','["Hypertensive nephrosclerosis: chronic vascular and glomerular damage from sustained hypertension. Histology: arteriolar hyalinosis, interlobular artery ''''onion-skin'''' intimal thickening, ischaemic glomerulosclerosis, tubular atrophy. Clinical features: slow eGFR decline, mild-moderate proteinuria (<1 g/day), long-standing hypertension — especially in Black patients (also called ''''benign nephrosclerosis''''). Diagnosis: often clinical (no biopsy needed if classic presentation). In Black patients: ACE inhibitors/ARBs are less effective for BP control alone but still reduce proteinuria; amlodipine is effective. AASK trial: ACE-I (ramipril) superior to metoprolol and amlodipine in reducing CKD progression in Black patients with hypertensive nephrosclerosis."]','A','Despite lower renin activity in Black patients, ACE inhibitors remain renoprotective in hypertensive nephrosclerosis — demonstrated by the AASK trial.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','easy','flashcard','What is the role of sodium restriction in hypertension management in CKD?','["Target: <2000 mg sodium (5 g NaCl) per day. Mechanisms of benefit: (1) Reduces extracellular fluid volume → reduces pre-load and BP; (2) Enhances efficacy of ACE inhibitors/ARBs — high sodium diet blunts their antiproteinuric and antihypertensive effects; (3) Reduces proteinuria directly; (4) Reduces CKD progression. Monitoring: 24-hour urine sodium collection is the gold standard for compliance. Sources: processed foods, bread, cured meats, canned foods, restaurant food — >70% of dietary sodium comes from processed food, not added salt."]','A','Sodium restriction potentiates the effect of ACE inhibitors — patients on ACE-I should specifically restrict sodium to maximise renoprotection and BP control.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','flashcard','What is phaeochromocytoma and how does it affect the kidney?','["Phaeochromocytoma: catecholamine-secreting tumour of adrenal medulla (10% extra-adrenal = paraganglioma). Presentation: Episodic or sustained hypertension with: headache, sweating, palpitations (the ''''triad''''). Renal effects: (1) Catecholamine-induced vasoconstriction → reduced renal blood flow → AKI in crisis; (2) Hypertensive nephrosclerosis from chronic hypertension; (3) Volume depletion from alpha-mediated vasoconstriction → apparent small plasma volume. Diagnosis: 24-hour urine fractionated metanephrines and catecholamines (most sensitive); plasma metanephrines. Imaging: CT/MRI adrenals; MIBG scan (if metastatic). Treatment: alpha-blockade FIRST (phenoxybenzamine or doxazosin) then beta-blockade, then surgical resection. Never give beta-blocker alone first → paradoxical hypertension from unblocked alpha receptors."]','A','Alpha-blockade must precede beta-blockade in phaeochromocytoma — giving a beta-blocker alone causes paradoxical hypertensive crisis from unopposed alpha stimulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','easy','flashcard','How do you classify hyponatraemia by serum osmolality and volume status?','["Step 1 — Serum osmolality: Isotonic (280–295): pseudohyponatraemia (hyperlipidaemia, hyperproteinaemia). Hypertonic (>295): hyperglycaemia, mannitol. Hypotonic (<280): true hyponatraemia → assess volume status. Step 2 — Volume status: HYPOVOLAEMIC: UNa <20 (extra-renal loss — diarrhoea, vomiting, third spacing); UNa >20 (renal loss — diuretics, Addison''''s, salt-wasting nephropathy). EUVOLAEMIC: SIADH (UNa >40, UOsm >100); hypothyroidism; polydipsia. HYPERVOLAEMIC: UNa <20 (heart failure, cirrhosis, nephrotic syndrome); UNa >20 (AKI/CKD with sodium retention failure)."]','A','Volume status is the most important clinical assessment in hyponatraemia — it narrows the differential to a manageable list and guides treatment.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','flashcard','What is the stepwise approach to managing severe symptomatic hyponatraemia?','["Symptoms: Seizures, obtundation, coma (Na usually <120 or rapidly falling). Treatment: 1. 3% NaCl 1–2 mL/kg IV bolus over 20 minutes (can repeat × 3); aim to raise Na by 4–6 mEq/L to stop acute symptoms. 2. Then slow maintenance: no more than 8–10 mEq/L per 24 hours total (maximum 18 mEq/L per 48 hours). 3. If Na was corrected too fast (overcorrection): give desmopressin (DDAVP) 2 mcg IV + 5% dextrose to re-lower Na and prevent ODS. 4. Monitor Na every 2–4 hours. ODS (osmotic demyelination syndrome): upper motor neurone signs, dysphagia, dysarthria, ''''locked-in'''' syndrome — delayed by 2–6 days after overcorrection."]','A','The 10 mEq/L/24h limit is the most critical rule in hyponatraemia management — ODS from overcorrection can be catastrophic and irreversible.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','flashcard','What are the causes of hyperkalaemia in CKD patients?','["1. Reduced renal excretion (GFR <20 mL/min — limited potassium secretion in distal nephron). 2. Metabolic acidosis — H+ shifts into cells, K+ shifts out. 3. Hypoaldosteronism (type 4 RTA — common in diabetic nephropathy): aldosterone deficiency/resistance reduces K+ secretion. 4. Drugs: ACE-I/ARB (reduce aldosterone), potassium-sparing diuretics (spironolactone, amiloride), NSAIDs, trimethoprim, heparin, calcineurin inhibitors. 5. High potassium diet. 6. Hypercatabolic states (tissue destruction, blood transfusion). Prevention: dietary K+ restriction (<2000 mg/day), avoid nephrotoxic drugs, novel binders (patiromer, sodium zirconium cyclosilicate)."]','A','Type 4 RTA in diabetic nephropathy (hyporeninism → hypoaldosteronism → hyperkalaemia + hyperchloraemic acidosis) is the most common cause of hyperkalaemia in CKD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','hard','flashcard','Outline the stepwise management of life-threatening hyperkalaemia (K+ >6.5 with ECG changes).','["STABILISE → SHIFT → REMOVE framework: 1. STABILISE cardiac membrane: IV calcium gluconate 10 mL 10% over 2–5 min (onset 1–3 min, duration 30–60 min; repeat if ECG changes persist). 2. SHIFT K+ into cells: (a) IV insulin 10 units in 50 mL 50% dextrose over 30 min (onset 30 min, lasts 4–6h, lowers K+ by 0.6–1.2 mEq/L); (b) Nebulised salbutamol 10–20 mg (β2 → Na/K ATPase → cellular uptake, lowers K+ by 0.5–1 mEq/L); (c) IV sodium bicarbonate 50 mEq (if acidaemic). 3. REMOVE K+ from body: Furosemide IV (renal excretion); Patiromer or SPS (GI removal — slow); Emergency haemodialysis (fastest, if above fails or cardiac arrest)."]','A','The three-step framework (Stabilise-Shift-Remove) prevents the common error of using binders alone, which act too slowly to prevent cardiac arrest.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','easy','flashcard','What are the ECG changes in hypokalaemia?','["ECG changes in hypokalaemia (K+ <3.5 mEq/L): Earliest: U-waves (positive deflection after T-wave — best seen in V2–V4); T-wave flattening/inversion; ST depression; Prolonged QT interval (increased risk of torsades de pointes). Severe (<2.5): ventricular arrhythmias, atrial tachycardia. Compare: Hyperkalaemia → peaked T-waves → QRS widening → sinusoidal → VF. Clinical: muscle weakness, fatigue, cramps, ileus, polyuria (nephrogenic DI in severe hypokalaemia). Treatment: KCl — oral preferred; IV if <2.5 or symptomatic (max 10–20 mEq/h via peripheral line; 40 mEq/h via central line)."]','A','U-waves are the hallmark ECG finding of hypokalaemia — prominent U-waves in V2–V4 should always trigger a potassium check.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','flashcard','What is the syndrome of inappropriate antidiuretic hormone secretion (SIADH)?','["SIADH = ADH released despite low plasma osmolality → water retention → dilutional hyponatraemia. Diagnostic criteria: Serum Na <135; Serum osmolality <275 mOsm/kg; Urine osmolality >100 (inappropriately concentrated); Urine Na >40 mEq/L; Clinically euvolaemic; Normal adrenal and thyroid function; No diuretics. Causes: CNS (meningitis, SAH, stroke, trauma); Pulmonary (pneumonia, TB, SCLC); Drugs (SSRIs, carbamazepine, cyclophosphamide, desmopressin, opioids); Post-surgical; Hypothyroidism (excluded by diagnosis). Treatment: Fluid restriction 500–1000 mL/day (first-line); demeclocycline; tolvaptan (V2 antagonist) for moderate-severe; 3% NaCl for severe symptoms."]','A','Tolvaptan is effective in SIADH but must not be used in liver disease (hepatotoxicity risk) and causes rapid fluid shifts requiring careful monitoring to prevent overcorrection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','flashcard','How does diabetes insipidus cause hypernatraemia?','["Diabetes insipidus (DI): deficiency of ADH (central DI) or renal resistance to ADH (nephrogenic DI) → inability to concentrate urine → massive dilute polyuria (up to 15 L/day) → hypernatraemia (if fluid intake inadequate). Presentation: Polyuria + polydipsia; dilute urine (osmolality <300, often <200 mOsm/kg) despite high serum osmolality. Water deprivation test + desmopressin challenge distinguishes central (responds to DDAVP) from nephrogenic DI (no response). Central DI causes: head trauma, pituitary surgery, tumours, meningitis. Nephrogenic DI causes: lithium (most common drug), hypercalcaemia, hypokalaemia, sickle cell disease. Treatment: Central — desmopressin (DDAVP) nasal spray or tablets. Nephrogenic — low-sodium diet + thiazide diuretic ± amiloride; stop lithium if possible."]','A','Lithium toxicity is the most common cause of acquired nephrogenic DI — affects up to 40% of long-term lithium users.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','hard','flashcard','What is the delta-delta ratio and how does it identify mixed acid-base disorders?','["Wait — this card is in the Electrolytes deck so link to hyponatraemia delta approach. Instead: What are the causes of hypercalcaemia and its renal effects? CALCIUM: Hypercalcaemia causes: PRIMARY hyperparathyroidism (elevated PTH, most common outpatient cause); Malignancy (PTHrP, osteolysis — most common inpatient); Vitamin D toxicity; Granulomatous disease (sarcoid, TB — 1α-hydroxylase activity); Thiazides (reduce renal calcium excretion). Renal effects: nephrogenic DI (aquaporin downregulation) → polyuria/polydipsia; nephrocalcinosis; AKI (volume depletion from polyuria, direct tubular toxicity); calcium nephrolithiasis. Treatment: IV saline 200–300 mL/h (volume expansion + calciuresis) + IV bisphosphonate (zoledronic acid — inhibits osteoclasts, onset 24–72h); calcitonin (rapid but short duration); dialysis for severe/refractory."]','A','IV saline remains the cornerstone of hypercalcaemia treatment — bisphosphonates take 24–72 hours to work, so hydration is the immediate priority.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','easy','flashcard','What are the causes and management of hypomagnesaemia?','["Causes: GI loss (diarrhoea, malabsorption, fistulae, proton pump inhibitors long-term); Renal loss (loop/thiazide diuretics, cisplatin, amphotericin, tacrolimus, gentamicin, alcohol); Redistribution (refeeding syndrome, DKA treatment). Clinical effects: Hypomagnesaemia causes refractory hypokalaemia (impairs K+ reabsorption in thick ascending limb — must correct Mg before K+ can be replenished); Hypomagnesaemia also causes refractory hypocalcaemia (impairs PTH release). ECG: prolonged QT, torsades de pointes. Treatment: IV magnesium sulphate (10–20 mmol over 30–60 min); oral MgO/MgSO4 for mild cases."]','A','The clinical pearl: refractory hypokalaemia or hypocalcaemia should always trigger a magnesium level check — magnesium must be repleted first.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','flashcard','What is pseudohyponatraemia and when should it be suspected?','["Pseudohyponatraemia: artefactually low serum sodium when sodium is measured by indirect ion-selective electrode in specimens with extreme hyperlipidaemia (triglycerides >10 mmol/L) or hyperproteinaemia (myeloma, Waldenström''''s macroglobulinaemia). Mechanism: lipid/protein occupies a fraction of measured plasma volume, diluting the sodium reading, but actual aqueous sodium concentration is normal. Diagnosis: Measured serum osmolality is normal (280–295 mOsm/kg); direct ISE measurement shows normal sodium. Clinical importance: No treatment for sodium — investigate and treat the underlying cause (hypertriglyceridaemia, myeloma). Distinct from hypertonic hyponatraemia (hyperglycaemia, mannitol) where serum osmolality is truly elevated."]','A','Pseudohyponatraemia = normal serum osmolality with low sodium reading — the osmolality gap gives it away immediately.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','easy','flashcard','What is the stepwise approach to ABG interpretation?','["Step 1 — pH: <7.35 = acidosis; >7.45 = alkalosis. Step 2 — Primary disorder: Check PaCO2 (normal 35–45) and HCO3 (normal 22–26). If pH low: CO2 high = respiratory acidosis; HCO3 low = metabolic acidosis. If pH high: CO2 low = respiratory alkalosis; HCO3 high = metabolic alkalosis. Step 3 — Compensation: Is compensation appropriate? (Winters'''' formula for metabolic acidosis: expected PaCO2 = 1.5 × HCO3 + 8 ± 2; for metabolic alkalosis: expected PaCO2 = 0.7 × ΔHCO3 + 40). Step 4 — Anion gap: AG = Na – (Cl + HCO3); normal 8–12 mEq/L. Step 5 — Delta ratio if HAGMA: ΔAG / ΔHCO3 (normal 1–2; <1 = concurrent NAGMA; >2 = concurrent metabolic alkalosis)."]','A','The 5-step ABG approach is systematic — never skip step 3 (compensation) or you will miss mixed disorders even when pH appears normal.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','flashcard','What are the causes of high anion gap metabolic acidosis (MUDPILES)?','["MUDPILES mnemonic: M = Methanol (formic acid); U = Uraemia (phosphate, sulphate, organic acids); D = Diabetic ketoacidosis (beta-hydroxybutyrate, acetoacetate); P = Propylene glycol (solvent in IV medications — lorazepam, phenobarbital); I = Isoniazid / Iron poisoning; L = Lactic acidosis (Type A: tissue hypoxia — sepsis, shock; Type B: drugs — metformin, nucleoside analogues, linezolid); E = Ethylene glycol (oxalic acid → calcium oxalate crystals → AKI); S = Salicylates (complex: mixed HAGMA + respiratory alkalosis). Always calculate osmolar gap in toxic ingestion: measured Osm – calculated Osm (2Na + Glu/18 + BUN/2.8); gap >10 suggests unmeasured osmoles (ethanol, methanol, ethylene glycol)."]','A','Osmolar gap >10 in a HAGMA patient should immediately raise suspicion for toxic alcohol ingestion (methanol, ethylene glycol) — start fomepizole/ethanol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','flashcard','What is the difference between acute and chronic respiratory acidosis on ABG?','["ACUTE respiratory acidosis: Rapid CO2 rise → immediate chemical buffering (no time for renal compensation). Expected HCO3 rise: 1 mEq/L per 10 mmHg ↑ CO2. pH typically <7.30 if severe. Causes: acute asthma, ARDS, airway obstruction, opioid overdose. CHRONIC respiratory acidosis: CO2 retained >3–5 days → renal compensation → HCO3 retained. Expected HCO3 rise: 3.5 mEq/L per 10 mmHg ↑ CO2. pH near-normal (compensated). Causes: COPD, chronic neuromuscular disease, obesity hypoventilation. Clinical importance: If HCO3 is much higher than expected, concurrent metabolic alkalosis (e.g., diuretics) is present — a mixed disorder."]','A','In COPD with CO2 retention, the elevated HCO3 is compensation, not metabolic alkalosis — the ratio (3.5 mEq/L per 10 mmHg CO2) distinguishes them.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','hard','flashcard','What is renal tubular acidosis (RTA) and what are the three main types?','["RTA: Normal AG metabolic acidosis (hyperchloraemic) from impaired renal acid excretion or bicarbonate wasting. Type 1 (DISTAL): Impaired H+ secretion in collecting duct → cannot acidify urine (pH >5.5 even in acidosis); hypokalaemia (K+ wasting); nephrocalcinosis and nephrolithiasis (from alkaline urine, low citrate). Causes: Sjögren''''s, amphotericin B, SLE. Treatment: sodium bicarbonate + potassium citrate. Type 2 (PROXIMAL): Defective HCO3 reabsorption in proximal tubule → bicarbonaturia; urine can acidify (pH <5.5); hypokalaemia; Fanconi syndrome. Causes: cystinosis, Wilson''''s, acetazolamide, tenofovir. Treatment: large doses of bicarbonate (leaks into urine). Type 4 (HYPERRENINAEMIC HYPOALDOSTERONISM): Aldosterone deficiency/resistance → impaired NH4+ excretion → HYPERKALEMIA (distinguishing feature); hyperchloraemic acidosis. Causes: diabetic nephropathy (type IV RTA), ACE-I, NSAIDs, heparin. Treatment: fludrocortisone (if aldosterone deficient) or dietary potassium restriction."]','A','The potassium level distinguishes RTA types: Types 1 and 2 cause HYPO-kalaemia; Type 4 causes HYPER-kalaemia — this is the most tested distinction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','easy','flashcard','What is metabolic alkalosis and what are the causes?','["Metabolic alkalosis: HCO3 >26 mEq/L, pH >7.45, PaCO2 appropriately elevated (hypoventilation). Classified by urinary chloride (Cl): SALINE-RESPONSIVE (UCl <25 mEq/L — Cl depleted): Vomiting (HCl loss + volume contraction); NGT suction; Diuretic therapy (loop/thiazide → Cl and K+ loss → contraction alkalosis); Post-hypercapnic alkalosis. Treatment: IV 0.9% NaCl (corrects chloride and volume). SALINE-RESISTANT (UCl >40 mEq/L — ongoing mineralocorticoid excess): Primary hyperaldosteronism (Conn''''s); Cushing''''s syndrome; Bartter''''s/Gitelman''''s syndrome; severe hypokalaemia; Liddle syndrome. Treatment: address underlying cause; spironolactone for aldosterone excess."]','A','Urine chloride is the key discriminating test in metabolic alkalosis — saline-responsive (UCl <25) responds to IV NaCl; saline-resistant (UCl >40) requires specific therapy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','flashcard','How does lactic acidosis develop in sepsis and what is type A vs type B?','["TYPE A lactic acidosis: Tissue hypoxia → anaerobic glycolysis → excess lactate. Causes: septic shock, cardiogenic shock, severe anaemia, CO poisoning, severe asthma. Lactate >4 mmol/L in septic shock = high mortality. Treatment: treat underlying cause (antibiotics, fluids, vasopressors); lactate clearance is a treatment target. TYPE B lactic acidosis: No tissue hypoxia — impaired hepatic lactate metabolism or increased production. Causes: Metformin (impairs complex I of mitochondrial respiratory chain; risk in AKI/dehydration); Nucleoside reverse transcriptase inhibitors (NRTIs); Thiamine deficiency; Malignancy (Warburg effect); Liver failure; Toxins (ethanol, linezolid). Treatment: stop causative drug; thiamine replacement if deficient."]','A','Metformin must be held in patients with AKI, contrast administration, or severe dehydration — risk of type B lactic acidosis from impaired lactate metabolism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','flashcard','What is the respiratory compensation for metabolic acidosis (Winters'''' formula) and what does deviation indicate?','["Winters'''' formula for expected PaCO2 in metabolic acidosis: Expected PaCO2 = 1.5 × [HCO3] + 8 ± 2 mmHg. If observed PaCO2 < expected: additional respiratory alkalosis present (e.g., aspirin poisoning, CNS lesion, liver disease). If observed PaCO2 > expected: additional respiratory acidosis present (e.g., COPD, opioids, muscle weakness). Clinical use: Always calculate expected compensation — a ''''normal-looking'''' PaCO2 in someone with HCO3 of 10 is actually abnormally high (should be ~23 mmHg), indicating a co-existing respiratory acidosis. PaCO2 rarely falls below 8–10 mmHg even with maximal hyperventilation."]','A','Kussmaul breathing (deep rapid breathing) in metabolic acidosis is the clinical equivalent of Winters'''' compensation — it is a respiratory drive response, not a disorder.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','hard','flashcard','What is the pathophysiology of salicylate poisoning and why does it cause a mixed ABG picture?','["Salicylate poisoning (aspirin overdose) causes a characteristic MIXED acid-base disorder: 1. RESPIRATORY ALKALOSIS: Salicylate directly stimulates the respiratory centre → hyperventilation → low PaCO2 (early finding, predominant in adults). 2. HIGH ANION GAP METABOLIC ACIDOSIS: Uncoupling of oxidative phosphorylation → lactic acid + ketoacids; also direct accumulation of salicylate as an unmeasured anion. Mixed picture: pH may be high (respiratory alkalosis dominates) or near-normal (effects cancel) or low (metabolic acidosis dominates — severe toxicity, especially in children). Treatment: alkaline diuresis (IV sodium bicarbonate → urine pH >7.5 → ion-trapping → enhanced salicylate excretion); haemodialysis for severe cases (salicylate dialysable)."]','A','The mixed respiratory alkalosis + HAGMA is unique to salicylate poisoning and pulmonary oedema — recognising this pattern triggers the osmolar gap and toxicology screen.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','easy','flashcard','What is Kussmaul breathing and in what conditions is it seen?','["Kussmaul breathing: deep, laboured, regular hyperventilation (not just rapid — it is also deep) representing maximum respiratory compensation for severe metabolic acidosis. Seen when pH <7.20 and HCO3 severely depressed. Conditions: Diabetic ketoacidosis (most classic), uraemic acidosis, lactic acidosis, salicylate poisoning, methanol/ethylene glycol poisoning. The patient''''s PaCO2 can drop to 8–10 mmHg. Clinically: the deep sighing respirations are visible to the examiner. Distinguished from: tachypnoea of pulmonary oedema/pneumonia (typically shallow and fast, not deep sighing)."]','A','Kussmaul breathing is a clinical sign of severe metabolic acidosis — the clinical equivalent of the compensatory hyperventilation seen on ABG. Always perform a fingerprick glucose and ABG in a patient with this breathing pattern.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','flashcard','What is the pathophysiology and management of DKA?','["DKA: Insulin deficiency → lipolysis → free fatty acids → ketone bodies (beta-hydroxybutyrate, acetoacetate) → HAGMA. Also: hyperglycaemia, volume depletion (osmotic diuresis), hyperkalaemia (intracellular shift from acidosis — but total body K+ depleted), Na depletion. Diagnosis: Glucose >11 mmol/L + ketones >3 mmol/L + pH <7.3 or HCO3 <15. Management (''''ABCDE of DKA''''): A = Airway/IV access; B = IV fluid resuscitation (0.9% NaCl 1L/h then taper); C = Insulin infusion 0.1 unit/kg/h (not until K+ replaced if <3.5); D = Dextrose added when glucose <14 mmol/L; E = Electrolyte replacement (K+ — ALWAYS replace before insulin; phosphate if very low). Resolution: pH >7.3, ketones <0.6, HCO3 >15. Complications: cerebral oedema (children), hypokalaemia (insulin-driven), hypoglycaemia."]','A','The commonest DKA management error is not replacing potassium before starting insulin — insulin drives K+ intracellularly causing life-threatening hypokalaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','easy','flashcard','What are the differences between haemodialysis and peritoneal dialysis?','["HAEMODIALYSIS (HD): Blood pumped through semipermeable membrane (dialyser) 3×/week × 4h. Clearance: diffusion + ultrafiltration. Access: AV fistula (preferred), graft, or CVC. Pros: efficient, monitoring. Cons: vascular access, haemodynamic instability, hospital attendance, heparin requirement. PERITONEAL DIALYSIS (PD): Dialysate infused into peritoneum via Tenckhoff catheter. Clearance: diffusion across peritoneal membrane + ultrafiltration driven by dextrose osmotic gradient. Types: CAPD (continuous ambulatory — 4 exchanges/day manually) or APD (automated — overnight machine). Pros: continuous, home-based, preserves residual renal function, no heparin. Cons: peritonitis risk, protein loss, abdominal distension, membrane failure over time."]','A','PD is better for residual renal function preservation and home independence; HD provides more efficient clearance — modality choice is individualised.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','flashcard','What are the complications of long-term haemodialysis?','["ACCESS: AV fistula stenosis/thrombosis; catheter infections (CRBSI); steal syndrome. CARDIOVASCULAR: Accelerated atherosclerosis (most common cause of death in dialysis patients); left ventricular hypertrophy; arrhythmias; sudden cardiac death. BONE/MINERAL: CKD-MBD → renal osteodystrophy, vascular calcification. ANAEMIA: EPO hyporesponsiveness; iron deficiency. INFECTION: Immunosuppression from uraemia; access infections; hepatitis B/C. NEUROLOGICAL: Dialysis dementia (aluminium toxicity — now rare); peripheral neuropathy; restless legs. AMYLOIDOSIS: β2-microglobulin amyloid (dialysis-related amyloidosis — causes carpal tunnel, joint pain after >10 years on dialysis). HAEMATOLOGICAL: Platelet dysfunction, bleeding."]','A','Cardiovascular disease kills 50% of dialysis patients — cardiovascular risk reduction (statins, BP control, anaemia treatment, phosphate control) is paramount.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','flashcard','What are the indications for renal transplantation and types of donors?','["Indications: ESRD (GFR <15 or dialysis-dependent); can be pre-emptive (before dialysis if GFR approaching 10). Contraindications: Active malignancy (<2–5 years remission); active infection; severe cardiovascular disease; non-compliance; active substance abuse. LIVING DONOR: Living related (first-degree relatives — best HLA matching); Living unrelated (e.g., spouse). Advantages: shorter wait, better outcomes, can be planned, longer graft survival. DECEASED DONOR: Brain-dead (DBD — donation after brainstem death); DCD (donation after circulatory death — increasing source). HLA matching: ABO compatibility essential; HLA-A, B, DR matching reduces rejection risk; crossmatch must be negative."]','A','Living donor transplantation has the best outcomes — 5-year graft survival ~90% (living) vs ~80% (deceased). Pre-emptive transplant (before dialysis) is ideal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','hard','flashcard','What are the types of transplant rejection and their management?','["HYPERACUTE (minutes to hours): Pre-formed donor-specific antibodies (DSA) → immediate complement activation → graft destruction. Prevention: ABO compatibility, negative crossmatch. Treatment: None — graft must be removed. ACUTE T-CELL MEDIATED (days to months): T-cell infiltration → tubulitis, interstitial inflammation. Diagnosed by biopsy (Banff criteria). Treatment: IV pulse methylprednisolone 500 mg × 3; rabbit anti-thymocyte globulin (rATG) for steroid-resistant cases. ACUTE ANTIBODY-MEDIATED (AMR): DSA → complement activation → C4d deposition in peritubular capillaries. Treatment: Plasmapheresis + IVIg + rituximab ± bortezomib. CHRONIC (months to years): Progressive graft fibrosis/atrophy. Diagnosed: tubular atrophy + interstitial fibrosis on biopsy. No effective treatment — optimise immunosuppression, control CVD risk."]','A','C4d staining in peritubular capillaries is the pathological hallmark of antibody-mediated rejection — it indicates complement activation by donor-specific antibodies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','easy','flashcard','What is the standard immunosuppression regimen after renal transplant?','["Triple therapy: 1. CALCINEURIN INHIBITOR (CNI): Tacrolimus (preferred) or cyclosporine — inhibit calcineurin → block IL-2 → suppress T-cell activation. 2. ANTIPROLIFERATIVE: Mycophenolate mofetil (MMF) or azathioprine — inhibit purine synthesis → suppress lymphocyte proliferation. 3. CORTICOSTEROIDS: Prednisolone (high-dose initially then taper to 5 mg/day maintenance or withdrawn). Induction (at transplant): Basiliximab (IL-2 receptor antagonist) or rATG (high-immunological risk patients). Monitoring: tacrolimus trough levels (target 8–12 ng/mL early, 5–8 ng/mL long-term); renal function; infection screening."]','A','Tacrolimus + MMF + prednisolone is the universal standard triple immunosuppression — tacrolimus trough monitoring prevents toxicity and under-immunosuppression.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','flashcard','What infections are transplant recipients particularly susceptible to and when?','["Timeline of post-transplant infections: FIRST MONTH: Surgical/nosocomial infections (wound, catheter, Gram-negatives, surgical-site, Candida). 1–6 MONTHS (peak immunosuppression): Opportunistic infections — CMV (most common viral: fever, leucopoenia, retinitis, colitis; prevented by valganciclovir prophylaxis); PJP/PCP (Pneumocystis jirovecii pneumonia — prevented by co-trimoxazole prophylaxis); BK polyomavirus (nephropathy — reduces immunosuppression); EBV → PTLD. Fungal: Aspergillus, Candida, Cryptococcus. AFTER 6 MONTHS: Community-acquired infections; late CMV; skin malignancies (SCC most common — from HPV + UV + immunosuppression); PTLD. Annual influenza vaccine; pneumococcal vaccine; avoid live vaccines post-transplant."]','A','CMV is the single most important opportunistic infection in the first year post-transplant — valganciclovir prophylaxis for 3–6 months is standard practice.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','flashcard','What is peritoneal dialysis adequacy and how is it measured?','["Adequacy measure: Weekly Kt/V (Kt/V ≥ 1.7/week for PD is the minimum KDIGO target; Kt/V ≥ 2.0 recommended for best outcomes). Also: total creatinine clearance ≥60 L/week/1.73m² (residual renal + peritoneal). Assessment: 24-hour PD effluent + 24-hour urine collection for simultaneous dialysate and renal contribution. Peritoneal Equilibration Test (PET): assesses peritoneal membrane transport type (high/low transporter) → guides CAPD vs APD choice. High transporters: absorb glucose fast → lose ultrafiltration → better on APD. Low transporters: clearance limited → may need more exchanges. Residual renal function contributes significantly early — preserve by avoiding nephrotoxins."]','A','Weekly Kt/V ≥1.7 is the minimum adequacy target for PD — adequacy testing at 1, 3, and 6 months then annually is standard practice.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','hard','flashcard','What are the principles of continuous renal replacement therapy (CRRT) in ICU?','["CRRT provides slow, continuous dialysis — preferred over intermittent HD in haemodynamically unstable patients. Modalities: CVVH (haemofiltration — convection, replacing filtrate with substitution fluid); CVVHD (haemodialysis — diffusion via counter-current dialysate); CVVHDF (combined — both convection and diffusion). Dose: 20–25 mL/kg/h effluent flow rate (KDIGO); higher doses (35 mL/kg/h) do not improve outcomes (RENAL, ARIF trials). Access: large-bore femoral, jugular, or subclavian CVC. Anticoagulation: systemic heparin or regional citrate anticoagulation (preferred — reduces bleeding, better filter life). Drug dosing: adjust all renally-cleared drugs — CRRT removes drugs predictably; pharmacy consultation essential. Electrolytes: monitor closely — phosphate, potassium depleted rapidly."]','A','Regional citrate anticoagulation is now preferred in CRRT — it anticoagulates the circuit only (citrate chelates calcium locally, reversed by calcium infusion post-filter), avoiding systemic bleeding risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','easy','flashcard','What is Kt/V and what is the target for haemodialysis adequacy?','["Kt/V is the measure of dialysis adequacy: K = dialyser clearance (mL/min); t = treatment time (min); V = volume of distribution of urea (~60% of body weight in L). A single-pool Kt/V ≥1.2 per session (3× weekly) is the minimum target. Equivalent to URR (urea reduction ratio) ≥65%. Methods: calculated from pre- and post-HD urea levels; formal Kt/V from urea kinetic modelling. If underdialysed (Kt/V <1.2): increase time per session, increase blood/dialysate flow rate, increase frequency. Poor outcomes associated with Kt/V <1.0. Adequacy testing: monthly URR; quarterly formal Kt/V."]','A','Kt/V ≥1.2 per session is the haemodialysis adequacy target — below this, uraemic complications increase and mortality rises.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','flashcard','What are the causes and management of arteriovenous fistula (AVF) failure in haemodialysis?','["AVF is the preferred vascular access (lowest infection and thrombosis rates). FAILURE types: 1. Failure to mature (non-maturation): fistula fails to develop adequate flow (>600 mL/min) or vein diameter (>6 mm) within 6–8 weeks. Causes: central venous stenosis, small veins, low arterial flow. Management: fistulogram + PTA, or fistula revision. 2. Thrombosis: sudden loss of thrill/bruit. Causes: hypotension, dehydration, compression, stenosis. Management: urgent thrombectomy or thombolysis within 24 hours. 3. Stenosis: progressive loss of flow or elevated venous pressures. Management: PTA (fistulogram). 4. Steal syndrome: ischaemia distal to fistula (cold, painful hand). Management: DRIL procedure or banding. 5. Aneurysm formation: risk of rupture."]','A','The ''''rule of 6s'''' for AVF maturity: flow >600 mL/min, diameter >6 mm, depth <6 mm, accessible length >6 cm, by 6 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','easy','flashcard','According to Ghana STG 2017, what is first-line treatment for acute uncomplicated cystitis in adults?','["1st Line: Nitrofurantoin oral, Adults 100 mg 6-hourly for 5–7 days (Evidence Rating: A). 2nd Line: Ciprofloxacin oral 500 mg 12-hourly for 5–7 days OR Cefuroxime oral 500 mg 12-hourly for 5–7 days. For symptomatic relief: Mist Potassium citrate 10 mL 8-hourly (if urine pH ≤6) — reduces dysuria; monitor potassium. AVOID nitrofurantoin: eGFR <30, in the third trimester of pregnancy (neonatal haemolysis risk), G6PD deficiency. PREGNANCY (UTI/cystitis): Cefuroxime oral 500 mg 12-hourly for 5–7 days (nitrofurantoin avoided at term)."]','A','Nitrofurantoin is the Ghana STG first-line for uncomplicated cystitis — the examiner will test this specific Ghana guidance rather than international guidelines.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','flashcard','What is the Ghana STG 2017 treatment for acute pyelonephritis (complicated UTI)?','["Complicated UTI (including pyelonephritis, catheter-related, stones, structural abnormalities): 1st Line: Ciprofloxacin IV 400 mg 8-12 hourly for 7 days (over 60 minutes). OR Gentamicin IV 40–80 mg 8-hourly for 7 days (if kidney function NORMAL — check creatinine first). OR Ceftriaxone IV 1–2 g daily for 7 days. Children: Amoxicillin + Clavulanic Acid IV or Cefuroxime IV. Step-down to oral when afebrile for 24–48 hours. Total course for pyelonephritis: 10–14 days for males; 7 days for females. Referral: very ill patients, recurrent UTI, persistent haematuria, congenital abnormalities."]','A','Ghana STG emphasises IV ciprofloxacin as first-line for complicated UTI/pyelonephritis — gentamicin is an alternative only if renal function is confirmed normal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','flashcard','What is the approach to recurrent UTI in women?','["Definition: ≥2 symptomatic UTIs in 6 months OR ≥3 in 12 months. Investigation: MSU culture each episode; check for anatomical abnormalities (ultrasound, cystoscopy if persistent haematuria); exclude diabetes, immunosuppression; check post-void residual urine. Non-antibiotic prevention: High fluid intake; post-coital and pre-coital voiding; front-to-back hygiene; avoid spermicidal contraceptives; topical vaginal oestrogen (post-menopausal); cranberry products (modest evidence, prevent adhesion of E. coli). Antibiotic prophylaxis options: Post-coital dose (nitrofurantoin 50–100 mg or trimethoprim 100 mg) OR Continuous low-dose prophylaxis (nitrofurantoin 50–100 mg nocte or trimethoprim 100 mg nocte for 6 months). Patient-initiated self-treatment: 3-day course at symptom onset."]','A','Post-coital prophylaxis (single dose immediately after sex) is highly effective for coitus-related recurrent UTIs with minimal antibiotic exposure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','hard','flashcard','What are the complications of untreated pyelonephritis?','["1. Perinephric abscess: collection of pus between renal capsule and Gerota''''s fascia. Suspect if persistent fever >5 days despite antibiotics. Diagnosis: CT KUB. Treatment: percutaneous drainage + antibiotics. 2. Emphysematous pyelonephritis: gas-forming bacteria in renal parenchyma — almost exclusive to diabetics. CT shows gas. Emergency nephrectomy or percutaneous drainage + antibiotics. High mortality (up to 80% without surgery). 3. Septic shock: bacteraemia → sepsis. Requires ICU, broad-spectrum IV antibiotics, pressors. 4. Renal papillary necrosis: ischaemic necrosis of renal papillae — associated with diabetes, sickle cell disease, analgesic nephropathy, NSAIDs. Presents with sloughed papillae in urine, AKI. 5. Chronic pyelonephritis → CKD (from repeated scarring)."]','A','Emphysematous pyelonephritis in a diabetic with persistent fever demands CT imaging immediately — survival requires surgical/percutaneous intervention, not antibiotics alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','easy','flashcard','What urine microscopy findings confirm a UTI?','["PYURIA: WBCs >10/mm³ (or >5 WBC/high-power field) — indicates inflammation. BACTERIURIA: Bacteria visible on Gram stain or culture ≥10⁵ CFU/mL (midstream clean-catch). HAEMATURIA: May be present (red blood cells — from mucosal inflammation). WBC CASTS: Indicate upper tract (renal pelvis/pyelonephritis) infection — distinguishes pyelonephritis from cystitis. Nitrite positive (dipstick): nitrate-reducing bacteria present (E. coli, Klebsiella, Proteus — NOT Enterococcus, Pseudomonas, Staph). Leucocyte esterase: marker of WBCs in urine. A positive leucocyte esterase + positive nitrite = >90% positive predictive value for UTI."]','A','WBC casts on urine microscopy indicate renal parenchymal infection (pyelonephritis/interstitial nephritis) — their presence elevates the diagnosis from lower to upper UTI.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','flashcard','How is UTI in pregnancy managed differently from non-pregnant women?','["Key differences: 1. ASYMPTOMATIC BACTERIURIA must be treated (25–30% progress to pyelonephritis; risk of preterm labour and low birth weight) — screen at first antenatal visit. 2. First-line Ghana STG: Cefuroxime oral 500 mg 12-hourly for 5–7 days (safe in pregnancy). 3. Avoid throughout pregnancy: Tetracyclines, trimethoprim (folate antagonist — first trimester), nitrofurantoin (at term — neonatal haemolysis), fluoroquinolones (cartilage toxicity in animal studies). 4. Confirmed culture-guided treatment. 5. Post-treatment MSU at 1 week and monthly thereafter (high relapse rate). 6. Pyelonephritis in pregnancy: IV ceftriaxone or cefuroxime; hospitalise."]','A','Asymptomatic bacteriuria in pregnancy is an absolute indication for antibiotic treatment — the only non-pregnant population where this is true (unlike catheterised patients).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','flashcard','What is emphysematous pyelonephritis and who is at risk?','["Emphysematous pyelonephritis (EPN): life-threatening necrotising infection of the renal parenchyma with intratissue gas production by gas-forming bacteria. Pathogens: E. coli (69%), Klebsiella (29%). Risk factors: Diabetes mellitus (90% of cases — hyperglycaemia provides substrate for CO2-generating fermentation); urinary tract obstruction. Presentation: Fever, flank pain, nausea/vomiting + evidence of systemic sepsis. CT KUB (not plain X-ray): gas within kidney (Type 1 — parenchymal gas = worse; Type 2 — collecting system gas ± perinephric = better). Management: IV broad-spectrum antibiotics (piperacillin-tazobactam or carbapenems) + glycaemic control + percutaneous drainage (preferred for Type 2) or emergency nephrectomy (Type 1, or drainage failure). Mortality: without surgery ~80%; with surgery/drainage ~20%."]','A','CT showing gas within the kidney in a febrile diabetic = emphysematous pyelonephritis — a surgical emergency, not just a complicated UTI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','hard','flashcard','What is the pathogenesis of recurrent UTI and how do E. coli virulence factors contribute?','["E. coli virulence factors enabling UTI: 1. TYPE 1 FIMBRIAE (mannose-sensitive): bind uroplakin receptors on urothelium → invasion into superficial umbrella cells → form intracellular bacterial communities (IBCs) — protected from antibiotics and immune killing (explains recurrence). 2. P FIMBRIAE (mannose-resistant): bind globoside on urothelial/GBM cells → facilitate upper tract invasion → pyelonephritis. 3. ALPHA-HAEMOLYSIN: pore-forming toxin → cell lysis. 4. AEROBACTIN: iron acquisition → bacterial survival. 5. CNF1 toxin: invades bladder cells. Consequence: Bladder reservoir of quiescent intracellular E. coli → ''''dormant'''' bacteria re-emerge → recurrent UTI despite adequate antibiotic treatment. Implication: explains why urine culture is negative between episodes despite true bacterial persistence."]','A','Intracellular bacterial communities (IBCs) of E. coli within urothelial cells explain treatment-refractory and recurrent UTIs — urine culture negative does not mean sterile bladder.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','easy','flashcard','What does pyuria without bacteriuria (''''sterile pyuria'''') suggest?','["Sterile pyuria = WBCs in urine without bacterial growth on standard culture. Causes: 1. Urogenital TB (''''sterile pyuria'''' is classic — acid-fast bacilli require Lowenstein-Jensen culture, ZN stain, or PCR); 2. Chlamydia trachomatis/Neisseria gonorrhoeae urethritis (not grown on standard culture); 3. Partially treated UTI; 4. Interstitial nephritis (drug-induced — NSAIDs, PPIs); 5. Urinary calculi; 6. Appendicitis or pelvic pathology adjacent to ureter; 7. Bladder malignancy. Investigation: AAFB stain and TB culture of early morning urine × 3 (if TB suspected); urethral swab for STIs; CT KUB; cystoscopy."]','A','Sterile pyuria is the classic presentation of renal tuberculosis — always send early morning urine × 3 for AAFB culture if sterile pyuria cannot be explained.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','flashcard','How should catheter-associated UTI (CAUTI) be diagnosed and managed?','["CAUTI: Symptoms (fever, rigors, altered mental status, flank pain, pelvic discomfort, suprapubic pain) in a catheterised patient + urine culture ≥10³ CFU/mL (lower threshold due to direct sampling). Key principle: Asymptomatic bacteriuria in catheterised patients should NOT be treated (will inevitably colonise; treatment selects resistant organisms). MANAGEMENT if symptomatic: (1) Remove or change catheter before sending culture; (2) Culture-guided antibiotics (5–7 days uncomplicated; 10–14 days if delayed response); (3) Empirical: ciprofloxacin or trimethoprim-sulfamethoxazole pending sensitivities; (4) PREVENTION: minimise catheter use; sterile insertion; closed drainage system; early removal (''''catheter rounds''''); silver-alloy catheters (modest evidence)."]','A','The single most effective intervention for CAUTI prevention is early catheter removal — audit catheter necessity daily and remove at earliest opportunity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','easy','flashcard','What are the four main types of renal calculi and their relative frequencies?','["1. CALCIUM OXALATE (most common, 70–80%): Radiopaque; associated with hypercalciuria, hyperoxaluria, hypocitraturia, low fluid intake. Subtypes: calcium oxalate monohydrate (harder, ESWL resistant) and dihydrate (softer). 2. CALCIUM PHOSPHATE (brushite, 10–15%): Radiopaque; associated with distal RTA (alkaline urine), hyperparathyroidism. 3. STRUVITE/TRIPLE PHOSPHATE (5–10%): Radiopaque; associated with urease-producing organisms (Proteus, Klebsiella); staghorn calculi. 4. URIC ACID (5–10%): Radiolucent; acidic urine (pH <5.5), gout, myeloproliferative disorders, high purine diet; can be dissolved with alkalinisation. 5. CYSTINE (<1%): Radiopaque (faintly); cystinuria — autosomal recessive; hexagonal crystals on urine microscopy."]','A','Uric acid stones are the only common stones that are radiolucent on plain X-ray — they require CT for diagnosis and can be dissolved medically with alkalinisation.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','flashcard','What is the management of acute ureteric colic?','["ANALGESIA: First-line — Diclofenac 75 mg IM or rectal (NSAID — reduces ureteric oedema, anti-prostaglandin, anti-spasmodic — superior to opioids for ureteric colic in RCTs); alternatively morphine 5–10 mg IV. ANTIEMETIC: Metoclopramide or ondansetron. HYDRATION: IV if vomiting; encourage oral fluids when tolerating. MEDICAL EXPULSIVE THERAPY (MET): Tamsulosin 0.4 mg daily OR nifedipine — alpha-1 blocker relaxes ureteric smooth muscle → facilitates stone passage. MET most effective for stones 5–10 mm in distal ureter. IMAGING: Non-contrast CT KUB (gold standard). WATCHFUL WAITING: Stones ≤5 mm → 68% pass spontaneously within 4 weeks. INDICATIONS FOR URGENT INTERVENTION: Obstruction + infection (emergency — risk of pyonephrosis); anuria (bilateral obstruction or single kidney); pain uncontrolled; AKI; stone >10 mm."]','A','Diclofenac (NSAID) is the preferred analgesic for ureteric colic — it is superior to opioids for pain control and additionally reduces ureteric oedema.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','flashcard','When is ESWL vs ureteroscopy vs PCNL chosen for renal stones?','["ESWL (extracorporeal shock wave lithotripsy): Best for: <2 cm stones in renal pelvis/upper ureter; soft stones (calcium oxalate dihydrate, uric acid); good anatomy; normal BMI. Contraindications: pregnancy, bleeding disorders, pacemaker, aortic aneurysm, morbid obesity. Works by fragmentation; pieces pass spontaneously (may cause Steinstrasse — ureteric column of fragments). URETEROSCOPY (URS) with laser lithotripsy: Best for: ureteric stones (all sizes); small renal stones; pregnancy-safe (no radiation during procedure); harder stones; obese patients. PCNL (percutaneous nephrolithotomy): Best for: stones >2 cm in renal pelvis or lower pole; staghorn calculi; ESWL failures; complex anatomy. Most invasive; requires general anaesthesia; risks: bleeding, infection, injury."]','A','Size and location determine approach: ≤5 mm = watchful waiting; 5–10 mm ureteric = MET/URS; <2 cm renal = ESWL/URS; >2 cm renal = PCNL; staghorn = PCNL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','hard','flashcard','What metabolic investigations should be performed in recurrent stone formers?','["24-HOUR URINE COLLECTION (complete evaluation): Volume (target >2.5 L/day); Calcium (normal <7.5 mmol/day men, <6.25 women; hypercalciuria >7.5); Oxalate (normal <0.5 mmol/day; hyperoxaluria >0.5); Citrate (low citrate = risk factor; citrate inhibits crystallisation); Uric acid (normal <4 mmol/day); pH (acidic = uric acid risk; alkaline = calcium phosphate/struvite risk); Phosphate; Sodium (high Na → high calciuria); Creatinine (confirms complete collection). BLOOD: Serum calcium (PTH if hypercalcaemic), uric acid, creatinine, phosphate, bicarbonate (RTA). STONE ANALYSIS: Type guides specific prevention. MEDICATIONS causing stones: calcium/vitamin D supplements, carbonic anhydrase inhibitors (topiramate → calcium phosphate), indinavir (crystals), triamterene."]','A','The 24-hour urine is the single most important investigation in recurrent stone disease — it quantifies every modifiable metabolic risk factor simultaneously.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','easy','flashcard','What is the role of potassium citrate in stone prevention?','["Potassium citrate prevents renal stones by: (1) Increasing urinary citrate (citrate binds calcium → reduces calcium oxalate/phosphate supersaturation; also directly inhibits crystal aggregation); (2) Alkalinising urine → dissolves uric acid stones (target urine pH 6.5–7.0) and prevents cystine stones (target pH >7.0). Indications: Hypocitraturia; Uric acid stone formers; Distal RTA (Type 1); Calcium oxalate stone disease with low urinary citrate; Cystinuria. Dose: 40–60 mEq/day in divided doses. Avoid in renal failure (risk of hyperkalaemia). The Ghana STG lists ''''Mist Potassium Citrate 10 mL 8-hourly'''' for bladder symptoms in cystitis — relates to the alkalinising/soothing effect in the bladder."]','A','Potassium citrate is dual-purpose: prevents calcium stones (by raising citrate) AND dissolves and prevents uric acid stones (by alkalinising urine) — the most versatile stone prevention agent.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','flashcard','What is the 24-hour urine profile in a patient with absorptive hypercalciuria?','["ABSORPTIVE HYPERCALCIURIA (most common type of hypercalciuria): Excessive GI absorption of calcium → high filtered calcium → exceeds tubular reabsorption → calciuria. 24-hour profile: Elevated urine calcium (>7.5 mmol/day); NORMAL serum calcium; NORMAL PTH; Elevated 1,25-dihydroxyvitamin D in Type 1. Types: Type 1 = diet-independent (defect in intestinal calcium transport); Type 2 = diet-dependent (corrects with calcium restriction). Treatment: Thiazide diuretic (hydrochlorothiazide 25–50 mg) reduces calciuria by enhancing distal tubular calcium reabsorption. Also: Moderate dietary calcium (1000 mg/day from food; avoid supplements), low sodium diet (reduces calciuria), low animal protein."]','A','Thiazide diuretics paradoxically reduce urinary calcium (by enhancing reabsorption in distal tubule) — the only antihypertensive that also prevents calcium stones.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','flashcard','What is the clinical presentation of cystine stones and how are they identified on urinalysis?','["Cystinuria: Autosomal recessive defect in SLC3A1/SLC7A9 → impaired proximal tubular reabsorption of cystine, ornithine, lysine, arginine (COLA mnemonic). Cystine is poorly soluble → forms stones. Presentation: Recurrent bilateral kidney stones from childhood/young adulthood; family history. Urinalysis: Hexagonal (flat hexagonal plate) cystine crystals on urine microscopy — pathognomonic. Sodium nitroprusside (cyanide-nitroprusside) test: positive (purple colour) — screens for cystinuria. 24-hour urine cystine: confirms diagnosis (normal <0.1 mmol/day; cystinuria >0.4 mmol/day). Stones: faintly opaque on KUB (due to sulphur content); CT shows stones. Treatment: Extreme fluid intake (>3 L/day to keep cystine below solubility threshold), urinary alkalinisation (pH >7.5), D-penicillamine or tiopronin (chelation therapy)."]','A','Hexagonal crystals on urine microscopy are pathognomonic of cystinuria — the only stone disease with a characteristic crystal morphology visible on routine microscopy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','hard','flashcard','What is the treatment of struvite (staghorn) calculi?','["Struvite stones form only in infection with urease-producing bacteria. Staghorn calculi fill the renal pelvis and calyces. Management requires BOTH stone removal AND infection eradication — antibiotics alone cannot dissolve struvite. 1. PCNL (percutaneous nephrolithotomy) — treatment of choice; single or staged procedures for complex staghorns. 2. ESWL (adjunct to PCNL in some cases). 3. Acetohydroxamic acid (AHA) — urease inhibitor; reduces stone growth; adjunct to surgery in patients unfit for intervention; significant side effects (haemolytic anaemia, DVT). 4. ANTIBIOTICS: Culture-guided, usually 4–6 weeks post-operatively; eradicate infection to prevent recurrence. 5. Prevent: treat any structural abnormality; remove foreign bodies; treat underlying urease-producing infection early."]','A','PCNL is the definitive treatment for staghorn calculi — antibiotics without stone removal will not cure struvite stones as the bacteria are protected within the stone matrix.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','easy','flashcard','What are the indications for urgent intervention in ureteric colic?','["URGENT/EMERGENCY INTERVENTION required when: 1. OBSTRUCTION + INFECTION: Obstructed ureter with fever/sepsis (pyonephrosis) = surgical emergency — risk of septic shock. Requires urgent decompression (ureteric stent or percutaneous nephrostomy) + IV antibiotics. 2. ANURIA: Bilateral ureteric obstruction or single functioning kidney. 3. PAIN UNCONTROLLED: Despite adequate analgesia. 4. LARGE STONES (>10 mm): Very unlikely to pass spontaneously (≈1% chance for stones >10 mm). 5. PROGRESSIVE AKI from obstruction. 6. Solitary kidney with obstruction. 7. Social factors: inability to attend for follow-up, no adult at home. Elective situations: recurrent UTIs; patient preference."]','A','Obstruction + infection (pyonephrosis) is the one absolute emergency in renal stone disease — delay in decompression leads to septic shock and renal loss.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','flashcard','How does distal renal tubular acidosis (Type 1 RTA) predispose to calcium phosphate stones?','["Distal RTA (Type 1): Impaired H+ secretion in α-intercalated cells of collecting duct → persistently alkaline urine (pH >5.5 even in systemic acidosis). Stone-forming effects: 1. ALKALINE URINE promotes calcium phosphate precipitation (solubility decreases as pH rises above 7.0). 2. HYPOCITRATURIA: Metabolic acidosis causes citrate reabsorption in proximal tubule (to buffer acid) → reduced urinary citrate → less citrate to inhibit crystallisation. 3. HYPERCALCIURIA: Acidosis mobilises calcium from bone buffering + reduces tubular calcium reabsorption. 4. NEPHROCALCINOSIS (diffuse calcium deposits in renal medulla) — classic radiological finding. Treatment: Potassium citrate (corrects acidosis + restores urinary citrate + alkalinises less — wait, alkalinisation in RTA is needed to correct acidosis, and citrate corrects hypocitraturia and does not further alkalinise beyond physiological range)."]','A','The triad of alkaline urine + hypercalciuria + hypocitraturia in distal RTA creates a perfect storm for calcium phosphate nephrolithiasis and nephrocalcinosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','easy','flashcard','What are the indications for renal biopsy?','["Absolute/strong indications: 1. Nephrotic syndrome in adults (to determine histological diagnosis before immunosuppression). 2. Rapidly progressive GN (crescentic GN) — urgent biopsy, treat while awaiting results. 3. Unexplained AKI with active urinary sediment (haematuria + proteinuria). 4. Significant proteinuria (>1 g/day) without obvious explanation. 5. Renal involvement in systemic disease (lupus, vasculitis, amyloidosis — to stage and guide therapy). 6. Haematuria with proteinuria or renal impairment. NOT usually biopsied: Isolated microhaematuria in young person (likely IgA or thin BM — biopsy does not change management). Longstanding diabetic nephropathy with classic presentation (clinical diagnosis sufficient). Small shrunken kidneys (high complication risk, low diagnostic yield)."]','A','Renal biopsy requires at least one accessible kidney with adequate size — always check coagulation (platelet >80,000, INR <1.5) and BP (<170/100) before proceeding.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','flashcard','What is the pathogenesis of membranous nephropathy?','["Primary MN: Circulating anti-PLA2R antibodies (in 70–80%) bind phospholipase A2 receptor on podocyte surface → immune complex formation in situ on outer surface of GBM (subepithelial). Complement (C5b-9 membrane attack complex) activated → podocyte injury → proteinuria. Histology: GBM thickening + ''''spikes'''' (GBM matrix surrounding subepithelial deposits) on silver stain; granular IgG + C4d on IF; subepithelial humps on EM. Anti-THSD7A antibodies: present in 3–5% of anti-PLA2R-negative primary MN. Secondary causes: HBV (children/endemic areas — anti-HBs Ag in deposits); HCV; SLE Class V (ISN); malignancy (lung, colon, breast — biopsy finding may precede cancer diagnosis); Drugs (gold, NSAIDs, penicillamine, mercury). ALWAYS exclude malignancy in older patients with MN."]','A','Anti-PLA2R titre correlates with disease activity in primary MN — rising titre predicts relapse, falling titre predicts remission, even before proteinuria changes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','flashcard','How is lupus nephritis managed across its ISN classes?','["Class I/II: No specific immunosuppression — hydroxychloroquine + ACE-I for proteinuria. Class III/IV (focal/diffuse proliferative): INDUCTION: MMF 2–3 g/day (preferred in non-European, women of childbearing age) OR Euro-lupus IV cyclophosphamide (500 mg fortnightly × 6) + methylprednisolone pulse → oral prednisolone 40–60 mg/day tapering. MAINTENANCE: MMF 1–2 g/day + prednisolone ≤7.5 mg/day for minimum 3 years. Class V (membranous): ACE-I + MMF or calcineurin inhibitor (tacrolimus/voclosporin — increasingly used). If Class V + III/IV: treat as Class IV. Class VI: No immunosuppression — prepare for RRT. ALL lupus nephritis: Hydroxychloroquine 200–400 mg/day (reduces flares and mortality). Monitoring: anti-dsDNA, C3, C4, urine PCR quarterly. Treat flares promptly."]','A','Hydroxychloroquine is the only drug used in ALL ISN classes of lupus nephritis — it reduces flares, protects against cardiovascular disease, and reduces lupus mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','hard','flashcard','What is the Oxford (MEST-C) classification of IgA nephropathy?','["Oxford classification assigns pathological risk scores: M (Mesangial hypercellularity): M0 (<50% of glomeruli with >4 mesangial cells/area) = better; M1 = worse. E (Endocapillary hypercellularity): E0 = none; E1 = present. S (Segmental sclerosis/adhesion): S0 = none; S1 = present. T (Tubular atrophy/interstitial fibrosis): T0 = <25%; T1 = 25–50%; T2 = >50%. C (Crescents): C0 = none; C1 = <25% crescents; C2 = ≥25%. Independent predictors of ESRD: M1, S1, T1/T2, and C2. Treatment implications: SGLT2 inhibitors (protective regardless of MEST-C); steroids considered if persistent proteinuria >1 g/day despite optimised supportive care; E1/C2 may benefit most from immunosuppression. Sparsentan (dual endothelin-RAAS antagonist) — novel agent reducing proteinuria in IgA nephropathy."]','A','T-score (tubular atrophy/interstitial fibrosis) is the strongest predictor of ESRD in IgA nephropathy — T2 (>50% fibrosis) indicates irreversible damage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','easy','flashcard','What is the immunofluorescence pattern in different glomerular diseases?','["LINEAR IgG: Anti-GBM disease (Goodpasture''''s). GRANULAR IgG + C3: Membranous nephropathy (subepithelial). IgA DOMINANT (mesangial): IgA nephropathy. IgG + IgA + IgM + C3 + C1q (''''full house''''): Lupus nephritis (Class III/IV). C3 DOMINANT (mesangial + capillary wall): C3 glomerulopathy (C3 nephritic factor, complement mutation). PAUCI-IMMUNE (negative IF): ANCA-associated vasculitis. IgG + C3 (granular, subendothelial/mesangial): MPGN Type I; post-infectious GN (''''humps''''). AMYLOID: Congo red positive with apple-green birefringence; negative IF or monoclonal light chain staining."]','A','''''Full house'''' immunofluorescence (IgG + IgA + IgM + C3 + C1q) is characteristic of lupus nephritis — it reflects the classical complement pathway activation by immune complexes.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','flashcard','What is C3 glomerulopathy and how does it differ from immune complex GN?','["C3 glomerulopathy: Disorder of alternative complement pathway dysregulation → excessive C3 consumption → C3 deposits in glomeruli WITHOUT immunoglobulin (pure C3 deposition on IF). Includes: Dense deposit disease (DDD/MPGN Type II — dense osmiophilic deposits in GBM on EM); C3 glomerulonephritis (C3GN — deposits less dense). Causes: C3 nephritic factor (autoantibody that stabilises C3 convertase → continuous complement activation); Mutations in CFH, CFI, CFB, MCP (complement regulators); MGUS (monoclonal immunoglobulin activates complement). Labs: Very low C3, normal C4 (alternative pathway bypass). Treatment: eculizumab (anti-C5 monoclonal antibody) for severe cases; FFP (source of CFH) in CFH deficiency; treat underlying MGUS. Distinguished from IC-GN by absence of immunoglobulins on IF."]','A','C3 dominant deposits on IF WITH negative immunoglobulin staining defines C3 glomerulopathy — low C3 with normal C4 points to alternative complement pathway dysregulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','flashcard','What is the approach to a patient with systemic vasculitis and renal involvement?','["ANCA-associated vasculitis (AAV): GPA (c-ANCA/anti-PR3), MPA (p-ANCA/anti-MPO), EGPA. Renal: pauci-immune focal necrotising GN with crescents. Assessment: Full ANCA titres (c-ANCA, p-ANCA, PR3-ANCA, MPO-ANCA); Renal biopsy (confirm diagnosis, assess severity — active vs chronic lesions); Urinalysis (haematuria, RBC casts); Creatinine trend; Chest X-ray/CT (pulmonary involvement in GPA, MPA); ENT assessment (GPA — sinusitis, saddle-nose deformity, subglottic stenosis). INDUCTION: Rituximab 375 mg/m² weekly × 4 (preferred for non-life-threatening; relapsing disease) OR cyclophosphamide IV/oral + methylprednisolone. Plasma exchange: if pulmonary haemorrhage or dialysis-dependent AKI (ADVOCATE trial — benefit in PR3-ANCA subgroup). MAINTENANCE: Azathioprine or rituximab for minimum 24 months. Monitor: ANCA titres, creatinine, urinalysis."]','A','Rituximab has become the preferred induction agent for ANCA vasculitis (non-inferior to cyclophosphamide, fewer side effects, effective for relapse) — the RAVE and RITUXVAS trials established this.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','hard','flashcard','What is the pathological classification of lupus nephritis by electron microscopy?','["EM deposits location defines ISN class: MESANGIAL (class I/II): Mesangial deposits only. SUBENDOTHELIAL (between endothelium and GBM — intraluminal side): Class III (focal) and IV (diffuse). ''''Wire-loop'''' lesions on LM = subendothelial deposits visible as eosinophilic acellular thickening. SUBEPITHELIAL (outside GBM, beneath podocytes): Class V (membranous). Tubuloreticular inclusions (''''viral footprints''''): Endoplasmic reticulum inclusions in endothelial cells on EM — seen in lupus nephritis (induced by interferon-α). Hump-shaped subepithelial deposits: Post-infectious GN (distinguishing from lupus). Class IV (worst): Diffuse subendothelial + mesangial deposits; active lesions: cellular crescents, fibrinoid necrosis; chronic lesions: glomerulosclerosis, fibrous crescents."]','A','Tubuloreticular inclusions (TRI) on EM are a hallmark of lupus nephritis — they represent interferon-α-induced changes in endothelial cells and are absent in primary GN.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','easy','flashcard','What is the role of hydroxychloroquine in lupus nephritis?','["Hydroxychloroquine (HCQ) 200–400 mg/day should be used in ALL patients with lupus nephritis unless contraindicated. Evidence-based benefits: 1. Reduces lupus flares (frequency and severity) — both renal and extra-renal. 2. Reduces relapse of lupus nephritis after remission. 3. Cardiovascular protection (lipid lowering, anti-thrombotic, anti-atherosclerotic). 4. Reduces organ damage accrual and improves overall survival. 5. Does not cause immunosuppression → no increased infection risk. 6. Safe in pregnancy (no increased fetal risk; may protect against neonatal lupus). Monitoring: annual ophthalmology review (risk of retinopathy with cumulative dose >5 mg/kg/day or >5 years). Safe across all CKD stages."]','A','HCQ is the only ''''background'''' immunomodulator used in all classes of lupus nephritis — it is one of the few drugs that actually improves survival in SLE.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','flashcard','What are the poor prognostic features in primary FSGS?','["Poor prognostic factors in FSGS: 1. Collapsing variant on biopsy (worst; associated with HIV, APOL1 genetic variants in Black patients). 2. Heavy nephrotic-range proteinuria at presentation (>8 g/day). 3. Hypertension at diagnosis. 4. Impaired GFR at presentation (creatinine >1.5 mg/dL). 5. Steroid resistance (failure to achieve remission after 12–16 weeks of steroids). 6. Genetic mutations (NPHS2, WT1, ACTN4, TRPC6 — do not respond to immunosuppression). 7. Segmental sclerosis >50% of biopsied glomeruli. 8. Tubular atrophy/interstitial fibrosis (T score). Treatment of steroid-resistant FSGS: calcineurin inhibitors (tacrolimus or cyclosporine) ± MMF; sparsentan; rituximab (limited evidence). 25% of FSGS patients reach ESRD within 10 years; collapsing variant may reach ESRD within 1–2 years."]','A','The collapsing variant of FSGS carries the worst prognosis (ESRD within 2 years) — APOL1 genetic risk variants (G1/G2) in Black patients predispose to this most aggressive form.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
